func requireRole(sess *auth.Session, allowed ...string) *AppError {
	if sess == nil {
		return Unauth("unauthorized", "authentication required")
	}
	if sess.ActiveRole == "" {
		return Conflict("role_not_selected", "select an active role")
	}
	if !roleOK(sess.ActiveRole, allowed...) {
		return Forbid("forbidden", "role not permitted")
	}
	return nil
}

func requireAdminOrDispatcher(sess *auth.Session) *AppError {
	return requireRole(sess, models.RoleAdministrator, models.RoleDispatcher)
}

