		return nil, NotFound("not_found", "user not found")
	}
	out := map[string]interface{}{
		"userId": u.ID.String(), "username": u.Username, "roles": u.Roles,
		"qualifications": u.Qualifications, "certifications": u.Certifications, "active": u.Active,
	}
	if u.Email != "" {
		out["email"] = u.Email
	}
	if u.FullName != "" {
		out["fullName"] = u.FullName
	}
	if u.Phone != "" {
		out["phone"] = u.Phone
	}
	return out, nil
}

func validRole(r string) bool {
	switch r {
	case models.RoleAdministrator, models.RoleDispatcher, models.RoleRequester,
		models.RoleCollectionProfessional, models.RoleDeliveryPartner,
		models.RoleNodeHandler, models.RoleLaboratoryTeam:
		return true
	}
	return false
}

func toStringSlice(v interface{}) []string {
	arr, ok := v.([]interface{})
	if !ok {
		if ss, ok2 := v.([]string); ok2 {
			return ss
		}
		return []string{}
	}
	out := make([]string, 0, len(arr))
	for _, x := range arr {
		if s, ok := x.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

func toUUIDSlice(v interface{}) []uuid.UUID {
	arr, ok := v.([]interface{})
	if !ok {
		return []uuid.UUID{}
	}
	out := make([]uuid.UUID, 0, len(arr))
	for _, x := range arr {
		if s, ok := x.(string); ok {
			if id, err := uuid.Parse(s); err == nil {
				out = append(out, id)
			}
		}
	}
	return out
}

func toCerts(v interface{}) []models.Certification {
	arr, ok := v.([]interface{})
	if !ok {
		return []models.Certification{}
	}
	out := []models.Certification{}
	for _, x := range arr {
		m, ok := x.(map[string]interface{})
		if !ok {
			continue
		}
		c := models.Certification{}
		c.Code, _ = m["code"].(string)
		c.Active, _ = m["active"].(bool)
		if ea, ok := m["expiresAt"].(string); ok && ea != "" {
			if t, err := time.Parse(time.RFC3339, ea); err == nil {
				c.ExpiresAt = &t
			}
		}
		if c.Code != "" {
			out = append(out, c)
		}
	}
	return out
}

func parseUUID(v interface{}) (uuid.UUID, error) {
	s, ok := v.(string)
	if !ok {
		return uuid.Nil, fmt.Errorf("not string")
	}
	return uuid.Parse(s)
}

func parseTime(v interface{}) (time.Time, error) {
	s, ok := v.(string)
	if !ok {
		return time.Time{}, fmt.Errorf("not string")
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		t, err = time.Parse(time.RFC3339Nano, s)
	}
	return t, err
}

func parseCoord(v interface{}) (models.Coordinate, error) {
	m, ok := v.(map[string]interface{})
	if !ok {
		return models.Coordinate{}, fmt.Errorf("invalid")
	}
	lat, ok1 := toFloat(m["latitude"])
	lng, ok2 := toFloat(m["longitude"])
	if !ok1 || !ok2 {
		return models.Coordinate{}, fmt.Errorf("invalid")
	}
	if lat < -90 || lat > 90 || lng < -180 || lng > 180 {
		return models.Coordinate{}, fmt.Errorf("out of range")
	}
	return models.Coordinate{Latitude: lat, Longitude: lng}, nil
}

func toFloat(v interface{}) (float64, bool) {
	switch t := v.(type) {
	case float64:
		return t, true
	case float32:
		return float64(t), true
	case int:
		return float64(t), true
	case json.Number:
		f, err := t.Float64()
		return f, err == nil
	default:
		return 0, false
	}
}

func toInt(v interface{}, def int) int {
	switch t := v.(type) {
	case float64:
		return int(t)
	case int:
		return t
	case json.Number:
		i, err := t.Int64()
		if err == nil {
			return int(i)
		}
	}
	return def
}

func toBool(v interface{}, def bool) bool {
	if b, ok := v.(bool); ok {
		return b
	}
	return def
}

