		return nil, err
	}
	username, _ := body["username"].(string)
	password, _ := body["initialPassword"].(string)
	if username == "" || password == "" {
		return nil, Bad("invalid_user", "username and password required")
	}
	roles := toStringSlice(body["roles"])
	if len(roles) == 0 {
		return nil, Bad("invalid_user", "roles required")
	}
