func (s *Service) UpdateUserAccess(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleAdministrator); err != nil {
		return nil, err
	}
	uid, err := parseUUID(body["userId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid userId")
	}
	roles := toStringSlice(body["roles"])
	active, _ := body["active"].(bool)
	quals := toStringSlice(body["qualifications"])
	certs := toCerts(body["certifications"])
	certJSON, _ := json.Marshal(certs)
	var assigned interface{}
	if v, ok := body["assignedLocationId"].(string); ok && v != "" {
		id, e := uuid.Parse(v)
