	_, err := coll.Indexes().CreateMany(ctx, modelsIdx)
	if err != nil {
		return err
	}
	// Touch collections so they exist after reset
	_, _ = coll.InsertOne(ctx, bson.M{"_bootstrap": true, "occurred_at": time.Now()})
