	}
	s.bumpNetwork(ctx)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "update_location", "location", id.String(), true, nil)
	return s.locationPublic(ctx, id)
}

func (s *Service) SetLocationStatus(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleAdministrator); err != nil {
		return nil, err
	}
	id, err := parseUUID(body["locationId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid locationId")
	}
	active := toBool(body["active"], true)
	tag, e := s.DB.PG.Exec(ctx, `UPDATE locations SET active=$1, updated_at=NOW() WHERE id=$2`, active, id)
	if e != nil {
		return nil, Internal(e.Error())
	}
	if tag.RowsAffected() == 0 {
		return nil, NotFound("not_found", "location not found")
	}
	s.bumpNetwork(ctx)
	return map[string]interface{}{"locationId": id.String(), "active": active}, nil
}

func (s *Service) SetLocationFunctionStatus(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleAdministrator); err != nil {
		return nil, err
	}
	id, err := parseUUID(body["locationId"])
	if err != nil {
		return nil, Bad("invalid_json", "invalid locationId")
	}
	fn, _ := body["function"].(string)
	active := toBool(body["active"], true)
	col := ""
	switch fn {
	case "collection_point":
		col = "fn_collection_point"
	case "transfer_point":
		col = "fn_transfer_point"
	case "hub":
		col = "fn_hub"
	case "laboratory":
		col = "fn_laboratory"
	default:
		return nil, Bad("invalid_location_function", "unknown function")
	}
	q := `UPDATE locations SET ` + col + `=$1, updated_at=NOW() WHERE id=$2`
	tag, e := s.DB.PG.Exec(ctx, q, active, id)
	if e != nil {
		return nil, Internal(e.Error())
	}
	if tag.RowsAffected() == 0 {
		return nil, NotFound("not_found", "location not found")
	}
	s.bumpNetwork(ctx)
	loc, aerr := s.locationPublic(ctx, id)
	if aerr != nil {
		return nil, aerr
	}
	return map[string]interface{}{
		"locationId": id.String(),
		"function":   fn,
		"active":     active,
		"functions":  loc["functions"],
	}, nil
}

func (s *Service) CreateConnection(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleAdministrator); err != nil {
		return nil, err
	}
	fromID, err := parseUUID(body["fromLocationId"])
	if err != nil {
		return nil, Bad("invalid_connection", "invalid fromLocationId")
	}
	toID, err := parseUUID(body["toLocationId"])
	if err != nil {
		return nil, Bad("invalid_connection", "invalid toLocationId")
	}
	if fromID == toID {
		return nil, Bad("invalid_connection", "from and to must differ")
	}
	travel := toInt(body["travelMinutes"], 0)
	if travel < 1 {
		return nil, Bad("invalid_connection", "travelMinutes must be >= 1")
	}
	cost, ok := toFloat(body["costUnits"])
	if !ok || cost < 0 {
		return nil, Bad("invalid_connection", "invalid costUnits")
	}
	cooled := toBool(body["cooled"], false)
	active := toBool(body["active"], true)
	// verify locations exist
	if _, aerr := s.getLocation(ctx, fromID); aerr != nil {
		return nil, Bad("invalid_connection", "from location not found")
	}
	if _, aerr := s.getLocation(ctx, toID); aerr != nil {
		return nil, Bad("invalid_connection", "to location not found")
	}
	id := uuid.New()
	_, e := s.DB.PG.Exec(ctx, `
		INSERT INTO connections (id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`, id, fromID, toID, travel, cost, cooled, active)
	if e != nil {
		return nil, Internal(e.Error())
	}
	s.bumpNetwork(ctx)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "create_connection", "connection", id.String(), true, nil)
	return map[string]interface{}{
		"connectionId": id.String(), "fromLocationId": fromID.String(), "toLocationId": toID.String(),
		"travelMinutes": travel, "costUnits": cost, "cooled": cooled, "active": active,
	}, nil
}

