		return nil, Bad("invalid_json", "invalid sampleTypeId")
	}
	st, aerr := s.getSampleType(ctx, id)
	if aerr != nil {
		return nil, aerr
	}
	container, _ := body["containerType"].(string)
	tmin, ok1 := toFloat(body["temperatureMinC"])
	tmax, ok2 := toFloat(body["temperatureMaxC"])
	if container == "" || !ok1 || !ok2 || tmin > tmax {
		return nil, Bad("invalid_handling_rule", "invalid handling")
	}
	qcr := st.QualifiedCollectorRequired
	if body["qualifiedCollectorRequired"] != nil {
		qcr = toBool(body["qualifiedCollectorRequired"], qcr)
	}
	rq := st.RequiredQualification
	if v, ok := body["requiredQualification"].(string); ok {
		rq = v
	}
	incomp := st.IncompatibleSampleTypes
	if body["incompatibleSampleTypes"] != nil {
		incomp = toUUIDSlice(body["incompatibleSampleTypes"])
	}
	cooled := st.RequiresCooledRoute
	if body["requiresCooledRoute"] != nil {
		cooled = toBool(body["requiresCooledRoute"], cooled)
	}
	batch := st.BatchingAllowed
	if body["batchingAllowed"] != nil {
		batch = toBool(body["batchingAllowed"], batch)
	}
	if st.Name == "Pulse" {
		batch = false
	}
	if st.Name == "Frost" {
		cooled = true
	}
	_, e := s.DB.PG.Exec(ctx, `
		UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3,
			temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6,
			requires_cooled_route=$7, batching_allowed=$8, updated_at=NOW() WHERE id=$9`,
		qcr, rq, container, tmin, tmax, incomp, cooled, batch, id)
	if e != nil {
		return nil, Internal(e.Error())
	}
	return s.sampleTypePublic(ctx, id)
}

