		}
		for _, a := range assignIDs {
			activeAssignmentIDs = append(activeAssignmentIDs, a.String())
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, Internal(err.Error())
	}

	s.Timeline(ctx, "sample_created", sess.UserID.String(), sess.ActiveRole, "sample", sampleID.String(), true,
		map[string]interface{}{"requestId": reqID.String(), "serviceability": serviceability}, &sampleID, journeyID, nil)
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, endpoint, "sample", sampleID.String(), true, map[string]interface{}{"requestId": reqID.String()})

	out := map[string]interface{}{
		"requestId": reqID.String(), "sampleId": sampleID.String(),
		"serviceability": serviceability, "serviceabilityReason": reason,
		"activeAssignmentIds": activeAssignmentIDs,
		"earliestCollectionAt": earliest.UTC().Format(time.RFC3339),
		"latestCollectionAt":   latest.UTC().Format(time.RFC3339),
		"alreadySealed":        presealed,
		"originType":           originType,
	}
	if journeyID != nil {
		out["journeyId"] = journeyID.String()
	}
	if svc.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = svc.TargetLaboratoryID.String()
	}
	if idem != "" {
		s.SaveIdempotent(ctx, idem, endpoint, reqHash, &sess.UserID, 201, map[string]interface{}{"data": out})
	}
	return out, nil
}

func statusOr(presealed bool, sealedStatus, unsealedStatus string) string {
	if presealed {
		return sealedStatus
	}
	return unsealedStatus
}

func boolTime(b bool) interface{} {
	if b {
		return time.Now().UTC()
	}
	return nil
}

func (s *Service) planJourneyTx(ctx context.Context, tx pgx.Tx, sampleID uuid.UUID, origin models.Coordinate, originType string,
	originNodeID *uuid.UUID, earliest, latest, deadline time.Time, st *models.SampleType, svc *ServiceabilityResult,
	presealed bool, actorID uuid.UUID) (uuid.UUID, []uuid.UUID, *AppError) {

	journeyID := uuid.New()
	path := svc.Path
	if len(path) == 0 {
		return uuid.Nil, nil, Conflict("no_valid_route", "no path")
	}
	routeMode := "direct"
	if len(path) > 2 {
		routeMode = "multi_stop"
	}
	est := earliest.Add(minutesDuration(svc.TravelMinutes))
	_, err := tx.Exec(ctx, `
		INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units,
			capacity_used, capacity_available, sample_ids, valid)
		VALUES ($1,1,$2,'planned',$3,$4,1,0,$5,TRUE)`,
		journeyID, routeMode, est, svc.CostUnits, []uuid.UUID{sampleID})
	if err != nil {
		return uuid.Nil, nil, Internal(err.Error())
	}

	// stops
	seq := 1
	// origin pickup stop (coordinate only if home/clinic)
	stopID := uuid.New()
	_, err = tx.Exec(ctx, `
		INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
		VALUES ($1,$2,$3,'pickup',$4,$5,0,$6,$7)`,
		stopID, journeyID, svc.CollectionNodeID, seq, earliest, origin.Latitude, origin.Longitude)
	if err != nil {
		return uuid.Nil, nil, Internal(err.Error())
	}
	seq++
	tCursor := earliest
	for i, locID := range path {
		stType := "handoff"
		if i == len(path)-1 {
			stType = "delivery"
		}
		// estimate
		if i == 0 {
			d := planning.HaversineKm(origin.Latitude, origin.Longitude,
				0, 0) // will set properly below
			_ = d
		}
		tCursor = tCursor.Add(20 * time.Minute)
		sid := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes)
			VALUES ($1,$2,$3,$4,$5,$6,5)`, sid, journeyID, locID, stType, seq, tCursor)
		if err != nil {
			return uuid.Nil, nil, Internal(err.Error())
		}
		seq++
	}

	assignIDs := []uuid.UUID{}
	needsCool := st.RequiresCooledRoute

	// collection assignment (unless presealed)
	if !presealed {
		aID := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, to_location_id)
			VALUES ($1,$2,$3,'collection',0,'pending',$4)`, aID, journeyID, sampleID, svc.CollectionNodeID)
		if err != nil {
			return uuid.Nil, nil, Internal(err.Error())
		}
		assignIDs = append(assignIDs, aID)
		if e := s.offerAssignmentTx(ctx, tx, aID, "collection", sampleID, st, svc.CollectionNodeID, nil); e != nil {
			// leave pending if no worker
			_ = e
		}
	}

	// transport legs along path
	for i := 0; i < len(path)-1; i++ {
		from := path[i]
		to := path[i+1]
		var connID *uuid.UUID
		if i < len(svc.ConnectionIDs) {
			c := svc.ConnectionIDs[i]
			connID = &c
		}
		aID := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, connection_id)
			VALUES ($1,$2,$3,'transport',$4,'pending',$5,$6,$7)`,
			aID, journeyID, sampleID, i+1, from, to, connID)
		if err != nil {
			return uuid.Nil, nil, Internal(err.Error())
		}
		assignIDs = append(assignIDs, aID)
		_ = s.offerAssignmentTx(ctx, tx, aID, "transport", sampleID, st, nil, nil)

		// reserve connection capacity
		if connID != nil {
			if e := s.reserveCapacityTx(ctx, tx, "connection", *connID, journeyID, sampleID, 1, needsCool); e != nil {
				return uuid.Nil, nil, e
			}
		}
	}

	// node assignments for intermediate nodes
	for i := 0; i < len(path)-1; i++ {
		nodeID := path[i]
		aID := uuid.New()
		_, err = tx.Exec(ctx, `
			INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, node_id, from_location_id, to_location_id)
			VALUES ($1,$2,$3,'node',$4,'pending',$5,$6,$7)`,
			aID, journeyID, sampleID, 100+i, nodeID, nodeID, path[i+1])
		if err != nil {
			return uuid.Nil, nil, Internal(err.Error())
		}
		assignIDs = append(assignIDs, aID)
		_ = s.offerAssignmentTx(ctx, tx, aID, "node", sampleID, st, &nodeID, nil)
		if e := s.reserveCapacityTx(ctx, tx, "location", nodeID, journeyID, sampleID, 1, needsCool); e != nil {
			return uuid.Nil, nil, e
		}
	}

	// laboratory assignment
	labID := *svc.TargetLaboratoryID
	aID := uuid.New()
	_, err = tx.Exec(ctx, `
		INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, laboratory_id, to_location_id)
		VALUES ($1,$2,$3,'laboratory',200,'pending',$4,$4)`, aID, journeyID, sampleID, labID)
	if err != nil {
		return uuid.Nil, nil, Internal(err.Error())
	}
	assignIDs = append(assignIDs, aID)
	_ = s.offerAssignmentTx(ctx, tx, aID, "laboratory", sampleID, st, &labID, nil)
	if e := s.reserveCapacityTx(ctx, tx, "location", labID, journeyID, sampleID, 1, needsCool); e != nil {
		return uuid.Nil, nil, e
	}

	return journeyID, assignIDs, nil
}

func (s *Service) reserveCapacityTx(ctx context.Context, tx pgx.Tx, resourceType string, resourceID, journeyID, sampleID uuid.UUID, units int, cooled bool) *AppError {
	if resourceType == "location" {
		var capU, resU, cCap, cRes int
		err := tx.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations WHERE id=$1 FOR UPDATE`, resourceID).
			Scan(&capU, &resU, &cCap, &cRes)
		if err != nil {
			return Internal(err.Error())
		}
		if cooled {
			if cCap > 0 && cRes+units > cCap {
				return Conflict("cooled_capacity_exhausted", "cooled capacity exhausted")
			}
			_, err = tx.Exec(ctx, `UPDATE locations SET cooled_reserved_units = cooled_reserved_units + $1 WHERE id=$2`, units, resourceID)
		} else {
			if capU > 0 && resU+units > capU {
				return Conflict("capacity_exhausted", "capacity exhausted")
			}
			_, err = tx.Exec(ctx, `UPDATE locations SET reserved_units = reserved_units + $1 WHERE id=$2`, units, resourceID)
		}
		if err != nil {
			return Internal(err.Error())
		}
	} else if resourceType == "connection" {
		var capU, resU, cCap, cRes int
		err := tx.QueryRow(ctx, `SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections WHERE id=$1 FOR UPDATE`, resourceID).
			Scan(&capU, &resU, &cCap, &cRes)
		if err != nil {
			return Internal(err.Error())
		}
		if cooled {
			if cCap > 0 && cRes+units > cCap {
				return Conflict("cooled_capacity_exhausted", "cooled capacity exhausted")
			}
			_, err = tx.Exec(ctx, `UPDATE connections SET cooled_reserved_units = cooled_reserved_units + $1 WHERE id=$2`, units, resourceID)
		} else {
			if capU > 0 && resU+units > capU {
				return Conflict("capacity_exhausted", "capacity exhausted")
			}
			_, err = tx.Exec(ctx, `UPDATE connections SET reserved_units = reserved_units + $1 WHERE id=$2`, units, resourceID)
		}
		if err != nil {
			return Internal(err.Error())
		}
	}
	_, err := tx.Exec(ctx, `
		INSERT INTO capacity_reservations (resource_type, resource_id, journey_id, sample_id, units, cooled, active)
		VALUES ($1,$2,$3,$4,$5,$6,TRUE)`, resourceType, resourceID, journeyID, sampleID, units, cooled)
	if err != nil {
		return Internal(err.Error())
	}
	return nil
}

func (s *Service) releaseJourneyCapacity(ctx context.Context, journeyID uuid.UUID) {
	rows, err := s.DB.PG.Query(ctx, `SELECT id, resource_type, resource_id, units, cooled FROM capacity_reservations WHERE journey_id=$1 AND active=TRUE`, journeyID)
	if err != nil {
		return
	}
	defer rows.Close()
	type res struct {
		id                     uuid.UUID
		resourceType           string
		resourceID             uuid.UUID
		units                  int
		cooled                 bool
	}
	var list []res
	for rows.Next() {
		var r res
		if rows.Scan(&r.id, &r.resourceType, &r.resourceID, &r.units, &r.cooled) == nil {
			list = append(list, r)
		}
	}
	for _, r := range list {
		if r.resourceType == "location" {
			if r.cooled {
				_, _ = s.DB.PG.Exec(ctx, `UPDATE locations SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - $1) WHERE id=$2`, r.units, r.resourceID)
			} else {
				_, _ = s.DB.PG.Exec(ctx, `UPDATE locations SET reserved_units = GREATEST(0, reserved_units - $1) WHERE id=$2`, r.units, r.resourceID)
			}
		} else {
			if r.cooled {
				_, _ = s.DB.PG.Exec(ctx, `UPDATE connections SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - $1) WHERE id=$2`, r.units, r.resourceID)
			} else {
				_, _ = s.DB.PG.Exec(ctx, `UPDATE connections SET reserved_units = GREATEST(0, reserved_units - $1) WHERE id=$2`, r.units, r.resourceID)
			}
		}
		_, _ = s.DB.PG.Exec(ctx, `UPDATE capacity_reservations SET active=FALSE WHERE id=$1`, r.id)
	}
}

func (s *Service) offerAssignmentTx(ctx context.Context, tx pgx.Tx, assignmentID uuid.UUID, kind string, sampleID uuid.UUID, st *models.SampleType, locationID *uuid.UUID, exclude []uuid.UUID) *AppError {
	role := ""
	switch kind {
	case "collection":
		role = models.RoleCollectionProfessional
	case "transport":
		role = models.RoleDeliveryPartner
	case "node":
		role = models.RoleNodeHandler
	case "laboratory":
		role = models.RoleLaboratoryTeam
	}
	rows, err := tx.Query(ctx, `
		SELECT id, roles, qualifications, certifications, available, capacity_units, decline_count, decline_penalty_until, assigned_location_id
		FROM users WHERE active=TRUE AND available=TRUE`)
	if err != nil {
		return Internal(err.Error())
	}
	defer rows.Close()
	type cand struct {
		id             uuid.UUID
		assignmentCount int
		declineCount   int
		penalty        bool
	}
	var cands []cand
	now := time.Now()
	for rows.Next() {
		var id uuid.UUID
		var roles, quals []string
		var certs []byte
		var available bool
		var capUnits, decCount int
		var penaltyUntil *time.Time
		var assignedLoc *uuid.UUID
		if err := rows.Scan(&id, &roles, &quals, &certs, &available, &capUnits, &decCount, &penaltyUntil, &assignedLoc); err != nil {
			continue
		}
		if containsUUID(exclude, id) {
			continue
		}
		if !containsStr(roles, role) {
			continue
		}
		if kind == "collection" && st.QualifiedCollectorRequired {
			ok := containsStr(quals, st.RequiredQualification) || containsStr(quals, st.Name)
			// also check certifications
			if !ok {
				continue
			}
		}
		if (kind == "node" || kind == "laboratory") && locationID != nil {
			if assignedLoc == nil || *assignedLoc != *locationID {
				continue
			}
		}
		pen := penaltyUntil != nil && penaltyUntil.After(now)
		var ac int
		_ = tx.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress','offered')`, id).Scan(&ac)
		cands = append(cands, cand{id: id, assignmentCount: ac, declineCount: decCount, penalty: pen})
	}
	if len(cands) == 0 {
		// flag exception if collection and no one ever available - deferred
		return Conflict("ineligible_worker", "no eligible worker")
	}
	// sort by penalty, workload, declines
	for i := 0; i < len(cands); i++ {
		for j := i + 1; j < len(cands); j++ {
			a, b := cands[i], cands[j]
			swap := false
			if a.penalty && !b.penalty {
				swap = true
			} else if a.penalty == b.penalty {
				if a.assignmentCount > b.assignmentCount {
					swap = true
				} else if a.assignmentCount == b.assignmentCount && a.declineCount > b.declineCount {
					swap = true
				}
			}
			if swap {
				cands[i], cands[j] = cands[j], cands[i]
			}
		}
	}
	chosen := cands[0].id
	exp := now.Add(models.OfferTimeout)
	_, err = tx.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$1, offer_expires_at=$2, updated_at=NOW() WHERE id=$3`,
		chosen, exp, assignmentID)
	if err != nil {
		return Internal(err.Error())
	}
	return nil
}

// json helper local
func jsonUnmarshal(b []byte, v interface{}) error {
	return jsonUnmarshalPkg(b, v)
}
