	}
	idem, _ := body["idempotencyKey"].(string)
	if idem == "" {
		return nil, Bad("idempotency_required", "required")
	}
	sampleID, err := parseUUID(body["sampleId"])
	if err != nil {
		return nil, Bad("invalid_json", "sampleId")
	}
	labID, err := parseUUID(body["laboratoryId"])
	if err != nil {
		return nil, Bad("invalid_json", "laboratoryId")
	}
	receivedAt, err := parseTime(body["receivedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "receivedAt")
	}
	var status string
	var journeyID *uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT status, active_journey_id FROM samples WHERE id=$1`, sampleID).Scan(&status, &journeyID)
	if err != nil {
		return nil, NotFound("not_found", "sample")
	}
	if status == "received" {
		return map[string]interface{}{
			"sampleId": sampleID.String(), "laboratoryId": labID.String(), "status": "received",
			"receivedAt": receivedAt.Format(time.RFC3339),
		}, nil
	}
	_, err = s.DB.PG.Exec(ctx, `
		UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2, current_holder_id=$3, updated_at=NOW() WHERE id=$4`,
		labID, receivedAt, sess.UserID, sampleID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE assignments SET status='completed', completed_at=$1 WHERE sample_id=$2 AND kind='laboratory' AND laboratory_id=$3`, receivedAt, sampleID, labID)
	if journeyID != nil {
		_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET status='completed', updated_at=NOW() WHERE id=$1`, *journeyID)
