func (s *Service) RecordLaboratoryException(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleLaboratoryTeam, models.RoleAdministrator, models.RoleDispatcher); err != nil {
		return nil, err
	}
	sampleID, err := parseUUID(body["sampleId"])
	if err != nil {
		return nil, Bad("invalid_json", "sampleId")
	}
	labID, err := parseUUID(body["laboratoryId"])
	if err != nil {
		return nil, Bad("invalid_json", "laboratoryId")
	}
	reason, _ := body["reason"].(string)
	observedAt, err := parseTime(body["observedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "observedAt")
	}
	exID := uuid.New()
	_, _ = s.DB.PG.Exec(ctx, `INSERT INTO exceptions (id, sample_id, laboratory_id, reason, observed_at, created_by) VALUES ($1,$2,$3,$4,$5,$6)`,
		exID, sampleID, labID, reason, observedAt, sess.UserID)
	exc := map[string]interface{}{"reason": reason, "laboratoryId": labID.String()}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1, updated_at=NOW() WHERE id=$2`, jsonMarshal(exc), sampleID)
	s.Timeline(ctx, "laboratory_exception", sess.UserID.String(), sess.ActiveRole, "sample", sampleID.String(), true, exc, &sampleID, nil, nil)
	return map[string]interface{}{"exceptionId": exID.String(), "sampleId": sampleID.String(), "status": "exception", "reason": reason}, nil
