func (s *Service) RecordHandlingCheckpoint(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	sampleID, err := parseUUID(body["sampleId"])
	if err != nil {
		return nil, Bad("invalid_json", "sampleId")
	}
	aID, err := parseUUID(body["assignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "assignmentId")
	}
	container, _ := body["containerType"].(string)
	temp, ok := toFloat(body["observedTemperatureC"])
	if !ok {
		return nil, Bad("invalid_json", "temperature")
	}
	recordedAt, err := parseTime(body["recordedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "recordedAt")
	}
	var locID *uuid.UUID
	if v, ok := body["locationId"].(string); ok && v != "" {
		if id, e := uuid.Parse(v); e == nil {
			locID = &id
		}
	}
	var tmin, tmax float64
	var status string
	err = s.DB.PG.QueryRow(ctx, `SELECT temperature_min_c, temperature_max_c, status FROM samples WHERE id=$1`, sampleID).Scan(&tmin, &tmax, &status)
	if err != nil {
		return nil, NotFound("not_found", "sample")
	}
	compliant := temp >= tmin && temp <= tmax
	cpID := uuid.New()
	_, _ = s.DB.PG.Exec(ctx, `
		INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_at, recorded_by)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, cpID, sampleID, aID, locID, container, temp, compliant, recordedAt, sess.UserID)
	if !compliant {
		exc := map[string]interface{}{"reason": "handling_checkpoint_failed", "temperature": temp, "containerType": container}
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET status='exception', exception=$1 WHERE id=$2`, jsonMarshal(exc), sampleID)
		status = "exception"
	}
	return map[string]interface{}{"checkpointId": cpID.String(), "sampleId": sampleID.String(), "compliant": compliant, "sampleStatus": status}, nil
}

func (s *Service) RecordWorkerLocation(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireRole(sess, models.RoleCollectionProfessional, models.RoleDeliveryPartner, models.RoleNodeHandler, models.RoleLaboratoryTeam); err != nil {
		return nil, err
	}
	aID, err := parseUUID(body["assignmentId"])
	if err != nil {
		return nil, Bad("invalid_json", "assignmentId")
	}
	coord, err := parseCoord(body["coordinate"])
	if err != nil {
		return nil, Bad("invalid_coordinate", "coordinate")
	}
	seq := toInt(body["sequence"], 0)
	if seq < 1 {
		return nil, Bad("invalid_json", "sequence")
	}
	recordedAt, err := parseTime(body["recordedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "recordedAt")
	}
	var sampleID uuid.UUID
	var workerID *uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `SELECT sample_id, worker_id FROM assignments WHERE id=$1`, aID).Scan(&sampleID, &workerID)
	if err != nil {
		return nil, NotFound("not_found", "assignment")
	}
	_, err = s.DB.PG.Exec(ctx, `
		INSERT INTO worker_locations (assignment_id, worker_id, latitude, longitude, sequence, recorded_at)
		VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (assignment_id, sequence) DO UPDATE SET latitude=$3, longitude=$4, recorded_at=$6`,
		aID, sess.UserID, coord.Latitude, coord.Longitude, seq, recordedAt)
	if err != nil {
