	if err != nil {
		return nil, Bad("invalid_json", "sampleId")
	}
	labID, err := parseUUID(body["laboratoryId"])
	if err != nil {
		return nil, Bad("invalid_json", "laboratoryId")
	}
	reason, _ := body["reason"].(string)
	observedAt, err := parseTime(body["observedAt"])
	if err != nil {
		return nil, Bad("invalid_time", "observedAt")
	}
