				"laboratory":       l.Functions.Laboratory,
			},
			"coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes,
		})
	}
	var version int
	_ = s.DB.PG.QueryRow(ctx, `SELECT serviceability_version FROM network_meta WHERE id=1`).Scan(&version)
	return map[string]interface{}{
		"user": user, "sampleTypes": sts, "locations": locOut,
		"serviceabilityVersion": version,
		"map": map[string]interface{}{
			"styleUrl": "/map/style.json", "center": []float64{77.5946, 12.9716}, "zoom": 11,
		},
