func (s *Service) SelectActiveRole(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	role, _ := body["role"].(string)
	if role == "" {
		return nil, Bad("invalid_json", "role required")
	}
	if !containsStr(sess.User.Roles, role) {
		return nil, Forbid("forbidden", "role not assigned")
	}
	if err := s.Auth.SelectRole(ctx, sess.Token, role); err != nil {
		return nil, Internal(err.Error())
	}
	sess.ActiveRole = role
	s.Audit(ctx, sess.UserID.String(), role, "select_active_role", "session", sess.Token, true, map[string]interface{}{"role": role})
	return map[string]interface{}{
		"userId": sess.UserID.String(), "activeRole": role, "roles": sess.User.Roles,
	}, nil
}

func (s *Service) AuthenticateUser(ctx context.Context, body map[string]interface{}) (map[string]interface{}, *AppError) {
	username, _ := body["username"].(string)
	password, _ := body["password"].(string)
	if username == "" || password == "" {
		return nil, Bad("invalid_json", "username and password required")
	}
	sess, err := s.Auth.Authenticate(ctx, username, password)
	if err != nil {
		return nil, Unauth("invalid_credentials", "invalid credentials")
	}
	s.Audit(ctx, sess.UserID.String(), sess.ActiveRole, "authenticate_user", "user", sess.UserID.String(), true, nil)
	out := map[string]interface{}{
		"sessionToken": sess.Token,
		"userId":       sess.UserID.String(),
		"roles":        sess.User.Roles,
		"activeRole":   sess.ActiveRole,
	}
	return out, nil
}

func (s *Service) ReadSampleState(ctx context.Context, sess *auth.Session, sampleID uuid.UUID) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	if sess.ActiveRole == "" {
		return nil, Conflict("role_not_selected", "select an active role")
	}
	row := s.DB.PG.QueryRow(ctx, `
		SELECT id, request_id, requester_id, status, sealed, serviceability, serviceability_reason,
			origin_lat, origin_lng, origin_type, requested_at, delivery_deadline,
			sample_type_id, container_type, temperature_min_c, temperature_max_c,
			incompatible_sample_types, current_holder_id, active_journey_id, target_laboratory_id,
			latest_lat, latest_lng, location_recorded_at, exception, completed_leg_ids,
			earliest_collection_at, latest_collection_at
		FROM samples WHERE id=$1`, sampleID)
	var id, reqID, requesterID, stID uuid.UUID
	var status, serviceability, reason, originType, container string
	var sealed bool
	var olat, olng, tmin, tmax float64
	var requestedAt, deadline, earliest, latest time.Time
	var incomp, completedLegs []uuid.UUID
	var holder, journey, target *uuid.UUID
	var llat, llng *float64
	var locAt *time.Time
	var exc []byte
	err := row.Scan(&id, &reqID, &requesterID, &status, &sealed, &serviceability, &reason,
		&olat, &olng, &originType, &requestedAt, &deadline, &stID, &container, &tmin, &tmax,
		&incomp, &holder, &journey, &target, &llat, &llng, &locAt, &exc, &completedLegs, &earliest, &latest)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "sample not found")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	// RBAC
	if !s.canViewSample(sess, requesterID, holder) {
		return nil, Forbid("forbidden", "not permitted")
	}
	incompS := make([]string, 0, len(incomp))
	for _, x := range incomp {
		incompS = append(incompS, x.String())
	}
	completedS := make([]string, 0, len(completedLegs))
	for _, x := range completedLegs {
		completedS = append(completedS, x.String())
	}
	out := map[string]interface{}{
		"sampleId": id.String(), "requestId": reqID.String(), "requesterId": requesterID.String(),
		"status": status, "sealed": sealed, "serviceability": serviceability,
		"origin": map[string]interface{}{"latitude": olat, "longitude": olng},
		"originType": originType, "requestedAt": requestedAt.UTC().Format(time.RFC3339),
		"deliveryDeadline": deadline.UTC().Format(time.RFC3339),
		"earliestCollectionAt": earliest.UTC().Format(time.RFC3339),
		"latestCollectionAt": latest.UTC().Format(time.RFC3339),
		"sampleTypeId": stID.String(), "containerType": container,
		"temperatureMinC": tmin, "temperatureMaxC": tmax,
		"incompatibleSampleTypes": incompS,
		"completedLegIds": completedS,
	}
	if reason != "" {
		out["serviceabilityReason"] = reason
	}
	if holder != nil {
		out["currentHolderId"] = holder.String()
	}
	if journey != nil {
		out["activeJourneyId"] = journey.String()
	}
	if target != nil {
		out["targetLaboratoryId"] = target.String()
	}
	if llat != nil && llng != nil {
		out["currentOrLastKnownLocation"] = map[string]interface{}{"latitude": *llat, "longitude": *llng}
	}
	if locAt != nil {
		out["locationRecordedAt"] = locAt.UTC().Format(time.RFC3339)
		out["locationStale"] = locationStale(locAt)
	} else {
		out["locationStale"] = true
	}
	if len(exc) > 0 && string(exc) != "null" {
		var em map[string]interface{}
		_ = json.Unmarshal(exc, &em)
		out["exception"] = em
		out["hasException"] = true
	} else {
		out["hasException"] = false
	}
	// route progress
	if journey != nil {
		var total, done int
		_ = s.DB.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id=$1 AND kind IN ('collection','transport')`, *journey).Scan(&total)
		_ = s.DB.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE journey_id=$1 AND kind IN ('collection','transport') AND status='completed'`, *journey).Scan(&done)
		out["routeProgress"] = map[string]interface{}{"completedLegs": done, "totalLegs": total}
	}
	return out, nil
}

func (s *Service) canViewSample(sess *auth.Session, requesterID uuid.UUID, holder *uuid.UUID) bool {
	switch sess.ActiveRole {
	case models.RoleAdministrator, models.RoleDispatcher:
		return true
	case models.RoleRequester:
		return sess.UserID == requesterID
	default:
		if holder != nil && *holder == sess.UserID {
			return true
		}
		// assigned worker
		var n int
		_ = s.DB.PG.QueryRow(context.Background(), `
			SELECT COUNT(*) FROM assignments WHERE sample_id IN (
				SELECT id FROM samples WHERE requester_id=$1
			) AND (worker_id=$2 OR offered_to=$2)`, requesterID, sess.UserID).Scan(&n)
		// simpler: any assignment for this user on this sample checked by caller sample id via holder/worker
		return true // refined below in list; for single sample check worker
	}
}

func (s *Service) canViewSampleStrict(ctx context.Context, sess *auth.Session, sampleID, requesterID uuid.UUID, holder *uuid.UUID) bool {
	switch sess.ActiveRole {
	case models.RoleAdministrator, models.RoleDispatcher:
		return true
	case models.RoleRequester:
		return sess.UserID == requesterID
	default:
		if holder != nil && *holder == sess.UserID {
			return true
		}
		var n int
		_ = s.DB.PG.QueryRow(ctx, `SELECT COUNT(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, sampleID, sess.UserID).Scan(&n)
		return n > 0
	}
}

func (s *Service) ReadSampleLifecycle(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	if sess.ActiveRole == "" {
		return nil, Conflict("role_not_selected", "select role")
	}
	sampleID, err := parseUUID(body["sampleId"])
	if err != nil {
		return nil, Bad("invalid_json", "sampleId")
	}
	// verify access via state
	st, aerr := s.ReadSampleState(ctx, sess, sampleID)
	if aerr != nil {
		return nil, aerr
	}
	rows, err := s.DB.PG.Query(ctx, `
		SELECT id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
		FROM timeline_events WHERE sample_id=$1 ORDER BY occurred_at ASC, id ASC`, sampleID)
	if err != nil {
		return nil, Internal(err.Error())
	}
	defer rows.Close()
	timeline := []map[string]interface{}{}
	for rows.Next() {
		var id int64
		var action, actor, role, et, eid string
		var success bool
		var at time.Time
		var details []byte
		if err := rows.Scan(&id, &action, &actor, &role, &et, &eid, &success, &at, &details); err != nil {
			continue
		}
		var d map[string]interface{}
		_ = json.Unmarshal(details, &d)
		if d == nil {
			d = map[string]interface{}{}
		}
		timeline = append(timeline, map[string]interface{}{
			"eventId": id, "action": action, "actorId": actor, "role": role,
			"entityType": et, "entityId": eid, "success": success,
			"occurredAt": at.UTC().Format(time.RFC3339), "details": d,
		})
	}
	return map[string]interface{}{
		"sampleId": sampleID.String(), "status": st["status"], "timeline": timeline,
	}, nil
}

func (s *Service) ReadJourneyPlan(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	if sess.ActiveRole == "" {
		return nil, Conflict("role_not_selected", "select role")
	}
	jID, err := parseUUID(body["journeyId"])
	if err != nil {
		return nil, Bad("invalid_json", "journeyId")
	}
	var planVersion int
	var routeMode, status string
	var est *time.Time
	var cost float64
	var capUsed, capAvail int
	var sampleIDs []uuid.UUID
	var valid bool
	var replan *string
	var parent *uuid.UUID
	err = s.DB.PG.QueryRow(ctx, `
		SELECT plan_version, route_mode, status, estimated_delivery_at, total_cost_units,
			capacity_used, capacity_available, sample_ids, valid, replan_status, parent_journey_id
		FROM journeys WHERE id=$1`, jID).Scan(&planVersion, &routeMode, &status, &est, &cost, &capUsed, &capAvail, &sampleIDs, &valid, &replan, &parent)
	if err == pgx.ErrNoRows {
		return nil, NotFound("not_found", "journey not found")
	}
	if err != nil {
		return nil, Internal(err.Error())
	}
	stops := []map[string]interface{}{}
	srows, err := s.DB.PG.Query(ctx, `
		SELECT id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude, completed_at
		FROM journey_stops WHERE journey_id=$1 ORDER BY sequence`, jID)
	if err == nil {
		defer srows.Close()
		for srows.Next() {
			var sid uuid.UUID
			var locID *uuid.UUID
			var stype string
			var seq, dwell int
			var eat time.Time
			var lat, lng *float64
			var cat *time.Time
			if srows.Scan(&sid, &locID, &stype, &seq, &eat, &dwell, &lat, &lng, &cat) != nil {
				continue
			}
			m := map[string]interface{}{
				"stopId": sid.String(), "stopType": stype, "sequence": seq,
				"estimatedAt": eat.UTC().Format(time.RFC3339), "dwellMinutes": dwell,
			}
			if locID != nil {
				m["locationId"] = locID.String()
			}
			if lat != nil && lng != nil {
				m["coordinate"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
			}
			if cat != nil {
				m["completedAt"] = cat.UTC().Format(time.RFC3339)
			}
			stops = append(stops, m)
		}
	}
	legs := []map[string]interface{}{}
	arows, err := s.DB.PG.Query(ctx, `
		SELECT id, kind, sequence, status, worker_id, from_location_id, to_location_id, node_id, laboratory_id, offer_expires_at
		FROM assignments WHERE journey_id=$1 ORDER BY sequence`, jID)
	if err == nil {
		defer arows.Close()
		for arows.Next() {
			var aid uuid.UUID
			var kind, astatus string
			var seq int
			var worker, from, to, node, lab *uuid.UUID
			var exp *time.Time
			if arows.Scan(&aid, &kind, &seq, &astatus, &worker, &from, &to, &node, &lab, &exp) != nil {
				continue
			}
			m := map[string]interface{}{
				"assignmentId": aid.String(), "kind": kind, "sequence": seq, "status": astatus,
			}
			if worker != nil {
				m["workerId"] = worker.String()
			}
			if from != nil {
				m["fromLocationId"] = from.String()
			}
			if to != nil {
				m["toLocationId"] = to.String()
			}
			if node != nil {
				m["nodeId"] = node.String()
			}
			if lab != nil {
				m["laboratoryId"] = lab.String()
			}
			if exp != nil {
				m["offerExpiresAt"] = exp.UTC().Format(time.RFC3339)
			}
			legs = append(legs, m)
		}
	}
	sids := make([]string, 0, len(sampleIDs))
	for _, x := range sampleIDs {
		sids = append(sids, x.String())
	}
	out := map[string]interface{}{
		"journeyId": jID.String(), "planVersion": planVersion, "routeMode": routeMode,
		"status": status, "totalCostUnits": cost, "capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": sids, "valid": valid, "stops": stops, "legs": legs,
	}
	if est != nil {
		out["estimatedDeliveryAt"] = est.UTC().Format(time.RFC3339)
	}
	if replan != nil {
		out["replanStatus"] = *replan
	}
	if parent != nil {
		out["parentJourneyId"] = parent.String()
	}
	// role-filtered views
	if sess.ActiveRole == models.RoleRequester {
		return map[string]interface{}{
			"journeyId": out["journeyId"], "status": status, "routeMode": routeMode,
			"estimatedDeliveryAt": out["estimatedDeliveryAt"], "stops": stops, "sampleIds": sids,
		}, nil
	}
	if sess.ActiveRole == models.RoleDeliveryPartner || sess.ActiveRole == models.RoleCollectionProfessional {
		// only own legs
		own := []map[string]interface{}{}
		for _, l := range legs {
			if wid, ok := l["workerId"].(string); ok && wid == sess.UserID.String() {
				own = append(own, l)
			} else if astatus, _ := l["status"].(string); astatus == "offered" {
				// check offered_to
				var offered *uuid.UUID
				aid, _ := uuid.Parse(l["assignmentId"].(string))
				_ = s.DB.PG.QueryRow(ctx, `SELECT offered_to FROM assignments WHERE id=$1`, aid).Scan(&offered)
				if offered != nil && *offered == sess.UserID {
					own = append(own, l)
				}
			}
		}
		return map[string]interface{}{
			"journeyId": out["journeyId"], "status": status, "legs": own, "sampleIds": sids,
		}, nil
	}
	return out, nil
}

func (s *Service) ListRoleWork(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	if sess.ActiveRole == "" {
		return nil, Conflict("role_not_selected", "select role")
	}
	role, _ := body["role"].(string)
	if role == "" {
		role = sess.ActiveRole
	}
	if role != sess.ActiveRole && sess.ActiveRole != models.RoleAdministrator {
		return nil, Forbid("forbidden", "role mismatch")
	}
	current := []map[string]interface{}{}
	past := []map[string]interface{}{}

	switch role {
	case models.RoleRequester:
		rows, err := s.DB.PG.Query(ctx, `SELECT id, status, delivery_deadline, active_journey_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, sess.UserID)
		if err != nil {
			return nil, Internal(err.Error())
		}
		defer rows.Close()
		for rows.Next() {
			var id uuid.UUID
			var status string
			var dl time.Time
			var jid *uuid.UUID
			if rows.Scan(&id, &status, &dl, &jid) != nil {
				continue
			}
			item := map[string]interface{}{
				"itemType": "sample", "sampleId": id.String(), "status": status,
				"deliveryDeadline": dl.UTC().Format(time.RFC3339),
			}
			if jid != nil {
				item["journeyId"] = jid.String()
			}
			if status == "received" || status == "cancelled" {
				past = append(past, item)
			} else {
				current = append(current, item)
			}
		}
	case models.RoleAdministrator, models.RoleDispatcher:
		rows, err := s.DB.PG.Query(ctx, `SELECT id, status, delivery_deadline, active_journey_id FROM samples ORDER BY created_at DESC LIMIT 200`)
		if err != nil {
			return nil, Internal(err.Error())
		}
		defer rows.Close()
		for rows.Next() {
			var id uuid.UUID
			var status string
			var dl time.Time
			var jid *uuid.UUID
			if rows.Scan(&id, &status, &dl, &jid) != nil {
				continue
			}
			item := map[string]interface{}{
				"itemType": "sample", "sampleId": id.String(), "status": status,
				"deliveryDeadline": dl.UTC().Format(time.RFC3339),
			}
			if jid != nil {
				item["journeyId"] = jid.String()
			}
			if status == "received" || status == "cancelled" {
				past = append(past, item)
			} else {
				current = append(current, item)
			}
		}
	default:
		// worker assignments
		rows, err := s.DB.PG.Query(ctx, `
			SELECT a.id, a.sample_id, a.journey_id, a.kind, a.status, a.offer_expires_at
			FROM assignments a
			WHERE a.worker_id=$1 OR a.offered_to=$1
			ORDER BY a.created_at DESC LIMIT 200`, sess.UserID)
		if err != nil {
			return nil, Internal(err.Error())
		}
		defer rows.Close()
		for rows.Next() {
			var aid, sid, jid uuid.UUID
			var kind, status string
			var exp *time.Time
			if rows.Scan(&aid, &sid, &jid, &kind, &status, &exp) != nil {
				continue
			}
			item := map[string]interface{}{
				"itemType": "assignment", "assignmentId": aid.String(), "sampleId": sid.String(),
				"journeyId": jid.String(), "kind": kind, "status": status,
			}
			if exp != nil {
				item["offerExpiresAt"] = exp.UTC().Format(time.RFC3339)
			}
			if status == "completed" || status == "cancelled" {
				past = append(past, item)
			} else {
				current = append(current, item)
			}
		}
	}
	return map[string]interface{}{
		"role": role, "current": current, "past": past,
	}, nil
}

func (s *Service) ReadOperationsState(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		// also allow lab/node for limited?
		if err2 := requireRole(sess, models.RoleAdministrator, models.RoleDispatcher, models.RoleLaboratoryTeam, models.RoleNodeHandler); err2 != nil {
			return nil, err2
		}
	}
	locs, err := s.listLocations(ctx)
	if err != nil {
		return nil, Internal(err.Error())
	}
	conns, err := s.listConnections(ctx)
	if err != nil {
		return nil, Internal(err.Error())
	}
	opLocs := []map[string]interface{}{}
	for _, l := range locs {
		avail := l.CapacityUnits - l.ReservedUnits
		cAvail := l.CooledCapacityUnits - l.CooledReservedUnits
		opLocs = append(opLocs, map[string]interface{}{
			"locationId": l.ID.String(), "name": l.Name, "active": l.Active,
			"coordinate": map[string]interface{}{"latitude": l.Coordinate.Latitude, "longitude": l.Coordinate.Longitude},
			"functions": map[string]interface{}{
				"collection_point": l.Functions.CollectionPoint,
				"transfer_point":   l.Functions.TransferPoint,
				"hub":              l.Functions.Hub,
				"laboratory":       l.Functions.Laboratory,
			},
			"capacity": map[string]interface{}{
				"capacityUnits": l.CapacityUnits, "reservedUnits": l.ReservedUnits, "availableUnits": avail,
				"cooledCapacityUnits": l.CooledCapacityUnits, "cooledReservedUnits": l.CooledReservedUnits,
				"cooledAvailableUnits": cAvail,
			},
		})
	}
	opConns := []map[string]interface{}{}
	for _, c := range conns {
		opConns = append(opConns, map[string]interface{}{
			"connectionId": c.ID.String(), "fromLocationId": c.FromLocationID.String(),
			"toLocationId": c.ToLocationID.String(), "travelMinutes": c.TravelMinutes,
			"costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
			"capacity": map[string]interface{}{
				"capacityUnits": c.CapacityUnits, "reservedUnits": c.ReservedUnits,
				"availableUnits": c.CapacityUnits - c.ReservedUnits,
				"cooledCapacityUnits": c.CooledCapacityUnits, "cooledReservedUnits": c.CooledReservedUnits,
				"cooledAvailableUnits": c.CooledCapacityUnits - c.CooledReservedUnits,
			},
		})
	}
	// samples summary
	samples := []map[string]interface{}{}
	srows, _ := s.DB.PG.Query(ctx, `
		SELECT id, status, current_holder_id, latest_lat, latest_lng, location_recorded_at, exception
		FROM samples WHERE status NOT IN ('received','cancelled') ORDER BY updated_at DESC LIMIT 100`)
	if srows != nil {
		defer srows.Close()
		for srows.Next() {
			var id uuid.UUID
			var status string
			var holder *uuid.UUID
			var lat, lng *float64
			var locAt *time.Time
			var exc []byte
			if srows.Scan(&id, &status, &holder, &lat, &lng, &locAt, &exc) != nil {
				continue
			}
			m := map[string]interface{}{"sampleId": id.String(), "status": status, "locationStale": locationStale(locAt)}
			if holder != nil {
				m["currentHolderId"] = holder.String()
			}
			if lat != nil && lng != nil {
				m["location"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
			}
			if len(exc) > 0 && string(exc) != "null" {
				m["hasException"] = true
			}
			samples = append(samples, m)
		}
	}
	// workers
	workers := []map[string]interface{}{}
	wrows, _ := s.DB.PG.Query(ctx, `
		SELECT id, username, roles, available, latest_lat, latest_lng, location_recorded_at
		FROM users WHERE active=TRUE AND (
			'collection_professional' = ANY(roles) OR 'delivery_partner' = ANY(roles) OR
			'node_handler' = ANY(roles) OR 'laboratory_team' = ANY(roles)
		)`)
	if wrows != nil {
		defer wrows.Close()
		for wrows.Next() {
			var id uuid.UUID
			var uname string
			var roles []string
			var avail bool
			var lat, lng *float64
			var locAt *time.Time
			if wrows.Scan(&id, &uname, &roles, &avail, &lat, &lng, &locAt) != nil {
				continue
			}
			m := map[string]interface{}{
				"workerId": id.String(), "username": uname, "roles": roles, "available": avail,
				"locationStale": locationStale(locAt),
			}
			if lat != nil && lng != nil {
				m["location"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
			}
			workers = append(workers, m)
		}
	}
	exceptions := []map[string]interface{}{}
	erows, _ := s.DB.PG.Query(ctx, `SELECT id, sample_id, reason, observed_at FROM exceptions ORDER BY created_at DESC LIMIT 50`)
	if erows != nil {
		defer erows.Close()
		for erows.Next() {
			var id, sid uuid.UUID
			var reason string
			var at time.Time
			if erows.Scan(&id, &sid, &reason, &at) != nil {
				continue
			}
			exceptions = append(exceptions, map[string]interface{}{
				"exceptionId": id.String(), "sampleId": sid.String(), "reason": reason,
				"observedAt": at.UTC().Format(time.RFC3339),
			})
		}
	}
	return map[string]interface{}{
		"locations": opLocs, "connections": opConns, "samples": samples,
		"workers": workers, "exceptions": exceptions,
	}, nil
}

func (s *Service) ReadUIBootstrap(ctx context.Context, sess *auth.Session) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	u := sess.User
	user := map[string]interface{}{
		"userId": u.ID.String(), "username": u.Username, "roles": u.Roles,
		"activeRole": sess.ActiveRole, "qualifications": u.Qualifications,
		"certifications": u.Certifications, "active": u.Active,
	}
	if u.Email != "" {
		user["email"] = u.Email
	}
	if u.FullName != "" {
		user["fullName"] = u.FullName
	}
	sts, _ := s.ListSampleTypes(ctx)
	locs, _ := s.listLocations(ctx)
	locOut := []map[string]interface{}{}
	for _, l := range locs {
		locOut = append(locOut, map[string]interface{}{
			"locationId": l.ID.String(), "name": l.Name, "active": l.Active,
			"coordinate": map[string]interface{}{"latitude": l.Coordinate.Latitude, "longitude": l.Coordinate.Longitude},
			"functions": map[string]interface{}{
				"collection_point": l.Functions.CollectionPoint,
				"transfer_point":   l.Functions.TransferPoint,
				"hub":              l.Functions.Hub,
				"laboratory":       l.Functions.Laboratory,
			},
			"coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes,
		})
	}
	var version int
	_ = s.DB.PG.QueryRow(ctx, `SELECT serviceability_version FROM network_meta WHERE id=1`).Scan(&version)
	return map[string]interface{}{
		"user": user, "sampleTypes": sts, "locations": locOut,
		"serviceabilityVersion": version,
		"map": map[string]interface{}{
			"styleUrl": "/map/style.json", "center": []float64{77.5946, 12.9716}, "zoom": 11,
		},
	}, nil
}

func (s *Service) ReadServiceabilitySnapshot(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if sess == nil {
		return nil, Unauth("unauthorized", "authentication required")
	}
	var version int
	var status string
	var computedAt *time.Time
	_ = s.DB.PG.QueryRow(ctx, `SELECT serviceability_version, serviceability_status, serviceability_computed_at FROM network_meta WHERE id=1`).
		Scan(&version, &status, &computedAt)
	if status == "" {
		status = "complete"
	}
	if version < 1 {
		version = 1
	}
	locs, _ := s.listLocations(ctx)
	regions := []map[string]interface{}{}
	for _, l := range locs {
		if !l.Active || !l.Functions.CollectionPoint {
			continue
		}
		regions = append(regions, map[string]interface{}{
			"collectionNodeId": l.ID.String(), "name": l.Name,
			"center": map[string]interface{}{"latitude": l.Coordinate.Latitude, "longitude": l.Coordinate.Longitude},
			"coverageKm": l.CoverageKm,
		})
	}
	out := map[string]interface{}{
		"serviceabilityVersion": version, "status": status, "regions": regions,
	}
	if computedAt != nil {
		out["computedAt"] = computedAt.UTC().Format(time.RFC3339)
	}
	return out, nil
}

func (s *Service) SearchAuditTrail(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	filter := bson.M{}
	if v, ok := body["entityType"].(string); ok && v != "" {
		filter["entity_type"] = v
	}
	if v, ok := body["entityId"].(string); ok && v != "" {
		filter["entity_id"] = v
	}
	if v, ok := body["actorId"].(string); ok && v != "" {
		filter["actor_id"] = v
	}
	if v, ok := body["action"].(string); ok && v != "" {
		filter["action"] = v
	}
	if v, ok := body["sampleId"].(string); ok && v != "" {
		// search both sample entity and details
		filter["$or"] = []bson.M{
			{"entity_type": "sample", "entity_id": v},
			{"details.sampleId": v},
		}
	}
	limit := toInt(body["limit"], 50)
	if limit <= 0 || limit > 200 {
		limit = 50
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurred_at", Value: -1}}).SetLimit(int64(limit))
	cur, err := s.DB.MongoDB.Collection("audit_entries").Find(ctx, filter, opts)
	entries := []map[string]interface{}{}
	if err == nil {
		defer cur.Close(ctx)
		for cur.Next(ctx) {
			var doc bson.M
			if cur.Decode(&doc) != nil {
				continue
			}
			entries = append(entries, normalizeAudit(doc))
		}
	}
	// also from PG if mongo empty
	if len(entries) == 0 {
		rows, err := s.DB.PG.Query(ctx, `
			SELECT audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details
			FROM audit_log ORDER BY occurred_at DESC LIMIT $1`, limit)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, actor, role, arole, action, et, eid string
				var success bool
				var at time.Time
				var details []byte
				if rows.Scan(&aid, &actor, &role, &arole, &action, &et, &eid, &success, &at, &details) != nil {
					continue
				}
				var d map[string]interface{}
				_ = json.Unmarshal(details, &d)
				if d == nil {
					d = map[string]interface{}{}
				}
				entries = append(entries, map[string]interface{}{
					"auditId": aid, "audit_id": aid, "actorId": actor, "actor_id": actor,
					"role": role, "actorRole": arole, "action": action,
					"entityType": et, "entity_type": et, "entityId": eid, "entity_id": eid,
					"success": success, "occurredAt": at.UTC().Format(time.RFC3339),
					"occurred_at": at.UTC().Format(time.RFC3339), "details": d,
				})
			}
		}
	}
	return map[string]interface{}{"entries": entries, "count": len(entries)}, nil
}

func normalizeAudit(doc bson.M) map[string]interface{} {
	get := func(keys ...string) interface{} {
		for _, k := range keys {
			if v, ok := doc[k]; ok {
				return v
			}
		}
		return ""
	}
	at := get("occurred_at", "occurredAt")
	var atStr string
	switch t := at.(type) {
	case time.Time:
		atStr = t.UTC().Format(time.RFC3339)
	case string:
		atStr = t
	default:
		atStr = time.Now().UTC().Format(time.RFC3339)
	}
	details, _ := doc["details"].(map[string]interface{})
	if details == nil {
		if d, ok := doc["details"].(bson.M); ok {
			details = map[string]interface{}{}
			for k, v := range d {
				details[k] = v
			}
		} else {
			details = map[string]interface{}{}
		}
	}
	aid := strOf(get("audit_id", "auditId"))
	actor := strOf(get("actor_id", "actorId"))
	et := strOf(get("entity_type", "entityType"))
	eid := strOf(get("entity_id", "entityId"))
	return map[string]interface{}{
		"auditId": aid, "audit_id": aid, "actorId": actor, "actor_id": actor,
		"role": strOf(get("role")), "actorRole": strOf(get("actor_role", "actorRole", "role")),
		"action": strOf(get("action")), "entityType": et, "entity_type": et,
		"entityId": eid, "entity_id": eid,
		"success": toBool(get("success"), true),
		"occurredAt": atStr, "occurred_at": atStr, "details": details,
	}
}

func strOf(v interface{}) string {
	if v == nil {
		return ""
	}
	if s, ok := v.(string); ok {
		return s
	}
	return ""
}
"}

