	newJID := uuid.New()
	_, err = s.DB.PG.Exec(ctx, `
		INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, sample_ids, valid)
		VALUES ($1,$2,1,'direct','planned',$3,TRUE)`, newJID, jID, sampleIDs)
	if err != nil {
		return nil, Internal(err.Error())
	}
	remain := []uuid.UUID{}
	splitSet := map[uuid.UUID]bool{}
	for _, x := range sampleIDs {
		splitSet[x] = true
		_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, newJID, x)
	}
	for _, x := range all {
		if !splitSet[x] {
