func (s *Service) MergeJourneys(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	ids := toUUIDSlice(body["journeyIds"])
	if len(ids) < 2 {
		return nil, Bad("invalid_json", "need at least 2 journeys")
	}
	// validate compatibility of samples
	allSamples := []uuid.UUID{}
	for _, jid := range ids {
		var sids []uuid.UUID
		var status string
		err := s.DB.PG.QueryRow(ctx, `SELECT sample_ids, status FROM journeys WHERE id=$1`, jid).Scan(&sids, &status)
		if err != nil {
			return nil, NotFound("not_found", "journey")
		}
		if status == "completed" || status == "cancelled" {
			return nil, Conflict("completed_work_immutable", "immutable")
		}
		allSamples = append(allSamples, sids...)
	}
	// check incompatibilities among sample types
	typeIDs := []uuid.UUID{}
	for _, sid := range allSamples {
		var stID uuid.UUID
		_ = s.DB.PG.QueryRow(ctx, `SELECT sample_type_id FROM samples WHERE id=$1`, sid).Scan(&stID)
		typeIDs = append(typeIDs, stID)
	}
	for _, tid := range typeIDs {
		st, aerr := s.getSampleType(ctx, tid)
		if aerr != nil {
			continue
		}
		if !st.BatchingAllowed {
			return nil, Conflict("batching_not_allowed", "sample type does not allow batching")
		}
		for _, other := range typeIDs {
			if containsUUID(st.IncompatibleSampleTypes, other) {
				return nil, Conflict("incompatible_samples", "incompatible sample types")
			}
		}
	}
	target := ids[0]
	merged := []uuid.UUID{}
	for _, jid := range ids {
		var sids []uuid.UUID
		_ = s.DB.PG.QueryRow(ctx, `SELECT sample_ids FROM journeys WHERE id=$1`, jid).Scan(&sids)
		merged = append(merged, sids...)
		if jid != target {
			_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET status='merged', updated_at=NOW() WHERE id=$1`, jid)
			for _, sid := range sids {
				_, _ = s.DB.PG.Exec(ctx, `UPDATE samples SET active_journey_id=$1 WHERE id=$2`, target, sid)
			}
		}
	}
	_, _ = s.DB.PG.Exec(ctx, `UPDATE journeys SET sample_ids=$1, route_mode='batched', plan_version=plan_version+1, updated_at=NOW() WHERE id=$2`, merged, target)
	var version int
	_ = s.DB.PG.QueryRow(ctx, `SELECT plan_version FROM journeys WHERE id=$1`, target).Scan(&version)
	return map[string]interface{}{"journeyId": target.String(), "sampleIds": uuidStrings(merged), "planVersion": version}, nil
}

