}

type handlerFunc func(ctx context.Context, sess *auth.Session, body map[string]interface{}) (interface{}, *service.AppError)

func (s *Server) wrap(h handlerFunc, needAuth bool, successStatus int) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		var sess *auth.Session
		if needAuth {
			var err error
			sess, err = s.sessionFrom(r)
			if err != nil {
				writeErr(w, service.Unauth("unauthorized", "authentication required"))
				return
			}
		}
		body, aerr := readBody(r)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		data, aerr := h(ctx, sess, body)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeJSON(w, successStatus, map[string]interface{}{"data": data})
	}
}

func (s *Server) sessionFrom(r *http.Request) (*auth.Session, error) {
	h := r.Header.Get("Authorization")
	if h == "" {
		return nil, auth.ErrUnauthorized
	}
	token := strings.TrimPrefix(h, "Bearer ")
	token = strings.TrimSpace(token)
	return s.Auth.GetSession(r.Context(), token)
}

func readBody(r *http.Request) (map[string]interface{}, *service.AppError) {
	if r.Body == nil {
		return map[string]interface{}{}, nil
	}
	defer r.Body.Close()
	b, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		return nil, service.Bad("invalid_json", "cannot read body")
	}
	if len(b) == 0 {
		return map[string]interface{}{}, nil
	}
	var m map[string]interface{}
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.UseNumber()
	if err := dec.Decode(&m); err != nil {
		return nil, service.Bad("invalid_json", "invalid json")
	}
	// convert json.Number to float64 for convenience
	normalizeNumbers(m)
	return m, nil
}

func normalizeNumbers(m map[string]interface{}) {
	for k, v := range m {
		switch t := v.(type) {
		case json.Number:
			if i, err := t.Int64(); err == nil {
				m[k] = float64(i)
			} else if f, err := t.Float64(); err == nil {
				m[k] = f
			} else {
				m[k] = t.String()
			}
		case map[string]interface{}:
			normalizeNumbers(t)
		case []interface{}:
			for i, x := range t {
				if n, ok := x.(json.Number); ok {
					if f, err := n.Float64(); err == nil {
						t[i] = f
					}
				} else if mm, ok := x.(map[string]interface{}); ok {
					normalizeNumbers(mm)
				}
			}
		}
	}
}

