type Server struct {
	Svc      *service.Service
	Auth     *auth.Service
	StaticDir string
	MapDir    string
	Router   *mux.Router
	upgrader websocket.Upgrader
}

func New(svc *service.Service, authSvc *auth.Service, staticDir, mapDir string) *Server {
	s := &Server{
		Svc: svc, Auth: authSvc, StaticDir: staticDir, MapDir: mapDir,
		upgrader: websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }},
	}
	s.Router = s.buildRouter()
	return s
}

func (s *Server) buildRouter() *mux.Router {
	r := mux.NewRouter()
	r.HandleFunc("/ready", s.handleReady).Methods("GET")

	api := r.PathPrefix("/api").Subrouter()
