action.file_text:
:root {
  --bg: #0f1419;
  --panel: #1a2332;
  --panel2: #243044;
  --border: #2d3a4f;
  --text: #e8eef7;
  --muted: #8b9bb4;
  --accent: #3b82f6;
  --accent2: #22c55e;
  --warn: #f59e0b;
  --danger: #ef4444;
  --radius: 10px;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}
* { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; background: var(--bg); color: var(--text); }
button, input, select, textarea {
  font: inherit; color: inherit; background: var(--panel2); border: 1px solid var(--border);
  border-radius: 8px; padding: 0.5rem 0.75rem;
}
button { cursor: pointer; background: var(--accent); border-color: transparent; color: white; font-weight: 600; }
button.secondary { background: var(--panel2); border-color: var(--border); color: var(--text); }
button.danger { background: var(--danger); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
input, select, textarea { width: 100%; }
label { display: block; font-size: 0.85rem; color: var(--muted); margin-bottom: 0.25rem; }
.field { margin-bottom: 0.75rem; }
.row { display: flex; gap: 0.75rem; flex-wrap: wrap; }
.row > * { flex: 1; min-width: 140px; }
.card {
  background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 1rem;
}
.grid { display: grid; gap: 1rem; }
.muted { color: var(--muted); }
.badge {
  display: inline-block; padding: 0.15rem 0.5rem; border-radius: 999px; font-size: 0.75rem;
  background: var(--panel2); border: 1px solid var(--border);
}
.badge.ok { background: rgba(34,197,94,0.15); color: #86efac; }
.badge.warn { background: rgba(245,158,11,0.15); color: #fcd34d; }
.badge.err { background: rgba(239,68,68,0.15); color: #fca5a5; }
.table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
.table th, .table td { text-align: left; padding: 0.5rem; border-bottom: 1px solid var(--border); vertical-align: top; }
.table th { color: var(--muted); font-weight: 600; }
.app-shell { display: grid; grid-template-columns: 260px 1fr; height: 100%; }
.sidebar {
  background: var(--panel); border-right: 1px solid var(--border); padding: 1rem; overflow: auto;
  display: flex; flex-direction: column; gap: 0.5rem;
}
.sidebar h1 { font-size: 1.05rem; margin: 0 0 0.5rem; }
.nav-btn {
  width: 100%; text-align: left; background: transparent; border: 1px solid transparent; color: var(--text);
  padding: 0.6rem 0.75rem;
}
.nav-btn.active, .nav-btn:hover { background: var(--panel2); border-color: var(--border); }
.main { display: flex; flex-direction: column; min-width: 0; height: 100%; }
.topbar {
  display: flex; justify-content: space-between; align-items: center; gap: 1rem;
  padding: 0.75rem 1rem; border-bottom: 1px solid var(--border); background: var(--panel);
}
.content { padding: 1rem; overflow: auto; flex: 1; }
.login-wrap {
  min-height: 100%; display: grid; place-items: center; padding: 2rem;
  background: radial-gradient(circle at top, #1e293b, #0f1419 60%);
}
.login-card { width: min(420px, 100%); }
.map-wrap { height: 420px; border-radius: var(--radius); overflow: hidden; border: 1px solid var(--border); }
.error-box {
  background: rgba(239,68,68,0.12); border: 1px solid rgba(239,68,68,0.4);
  color: #fecaca; padding: 0.75rem; border-radius: 8px; margin-bottom: 0.75rem;
}
.success-box {
  background: rgba(34,197,94,0.12); border: 1px solid rgba(34,197,94,0.4);
  color: #bbf7d0; padding: 0.75rem; border-radius: 8px; margin-bottom: 0.75rem;
}
.tabs { display: flex; gap: 0.5rem; margin-bottom: 1rem; flex-wrap: wrap; }
.tab { background: var(--panel2); }
.tab.active { background: var(--accent); }
.timeline { border-left: 2px solid var(--border); margin-left: 0.5rem; padding-left: 1rem; }
.timeline-item { margin-bottom: 0.75rem; position: relative; }
.timeline-item::before {
  content: ''; position: absolute; left: -1.35rem; top: 0.35rem; width: 0.55rem; height: 0.55rem;
  border-radius: 50%; background: var(--accent);
}
pre.json {
  background: #0b1220; border: 1px solid var(--border); border-radius: 8px;
  padding: 0.75rem; overflow: auto; font-size: 0.8rem;
}
@media (max-width: 900px) {
  .app-shell { grid-template-columns: 1fr; }
  .sidebar { border-right: none; border-bottom: 1px solid var(--border); }
}

