import { FormEvent, useState } from 'react'

export default function LoginPage({
  onLogin, error, loading,
}: {
  onLogin: (u: string, p: string) => void
  error?: string
  loading?: boolean
}) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')

  function submit(e: FormEvent) {
    e.preventDefault()
    onLogin(username.trim(), password)
  }

  return (
    <div className="login-wrap">
      <form className="card login-card" onSubmit={submit}>
        <h2 style={{ marginTop: 0 }}>Lab Sample Pickup & Delivery</h2>
        <p className="muted">Sign in with your assigned account. The first administrator is created from environment variables on first start.</p>
        {error && <div className="error-box">{error}</div>}
        <div className="field">
          <label>Username</label>
          <input value={username} onChange={e => setUsername(e.target.value)} autoComplete="username" required />
        </div>
        <div className="field">
          <label>Password</label>
          <input type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required />
        </div>
        <button type="submit" disabled={loading} style={{ width: '100%' }}>
          {loading ? 'Signing in…' : 'Sign in'}
        </button>
      </form>
    </div>
  )
}

