import { useEffect, useMemo, useState } from 'react'
import {
  api, AuthSession, clearSession, getSession, roleLabel, saveSession, Role
} from './api'
import LoginPage from './pages/LoginPage'
import WorkPage from './pages/WorkPage'
import RequestPage from './pages/RequestPage'
import OpsPage from './pages/OpsPage'
import AdminPage from './pages/AdminPage'
import SamplePage from './pages/SamplePage'
import MapPage from './pages/MapPage'
import AuditPage from './pages/AuditPage'

type Page = 'work' | 'request' | 'ops' | 'admin' | 'sample' | 'map' | 'audit'

const pagesForRole = (role: Role): { id: Page; label: string }[] => {
  const common = [
    { id: 'work' as Page, label: 'My Work' },
    { id: 'sample' as Page, label: 'Sample Lookup' },
    { id: 'map' as Page, label: 'Live Map' },
  ]
  if (role === 'requester') {
    return [
      { id: 'request', label: 'Requests' },
      { id: 'sample', label: 'Sample Lookup' },
      { id: 'map', label: 'Live Map' },
    ]
  }
  if (role === 'dispatcher' || role === 'administrator') {
    return [
      ...common,
      { id: 'ops', label: 'Operations' },
      { id: 'request', label: 'Requests' },
      { id: 'audit', label: 'Audit' },
      ...(role === 'administrator' ? [{ id: 'admin' as Page, label: 'Admin' }] : []),
    ]
  }
  return common
}

export default function App() {
  const [session, setSession] = useState<AuthSession | null>(() => getSession())
  const [page, setPage] = useState<Page>('work')
  const [bootstrap, setBootstrap] = useState<any>(null)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const nav = useMemo(() => session ? pagesForRole(session.activeRole) : [], [session])

  useEffect(() => {
    if (!session) return
    let cancelled = false
    ;(async () => {
      try {
        const data = await api('/ui/bootstrap')
        if (!cancelled) setBootstrap(data)
      } catch (e: any) {
        if (e?.status === 401) {
          clearSession()
          setSession(null)
        }
      }
    })()
    return () => { cancelled = true }
  }, [session?.token, session?.activeRole])

  useEffect(() => {
    if (!session) return
    const allowed = pagesForRole(session.activeRole).map(p => p.id)
    if (!allowed.includes(page)) setPage(allowed[0])
  }, [session?.activeRole])

  async function onLogin(username: string, password: string) {
    setError('')
    setLoading(true)
    try {
      const data = await api<any>('/authenticate-user', {
        auth: false,
        body: { username, password },
      })
      const s: AuthSession = {
        token: data.accessToken || data.token,
        userId: data.userId,
        username: data.username || username,
        displayName: data.displayName || data.username || username,
        roles: data.roles || [],
        activeRole: data.activeRole || (data.roles && data.roles[0]),
        assignedLocationIds: data.assignedLocationIds || [],
        certifications: data.certifications || [],
      }
      saveSession(s)
      setSession(s)
      setPage(pagesForRole(s.activeRole)[0].id)
    } catch (e: any) {
      setError(e.message || 'Login failed')
    } finally {
      setLoading(false)
    }
  }

  async function switchRole(role: Role) {
    if (!session || role === session.activeRole) return
    setError('')
    try {
      const data = await api<any>('/select-active-role', { body: { role } })
      const next = {
        ...session,
        activeRole: (data.activeRole || role) as Role,
        roles: data.roles || session.roles,
      }
      saveSession(next)
      setSession(next)
    } catch (e: any) {
      setError(e.message || 'Role switch failed')
    }
  }

  function logout() {
    clearSession()
    setSession(null)
    setBootstrap(null)
  }

  if (!session) {
    return <LoginPage onLogin={onLogin} error={error} loading={loading} />
  }

  return (
    <div className="app-shell">
      <aside className="sidebar">
        <h1>Lab Sample Network</h1>
        <div className="muted" style={{ marginBottom: '0.5rem' }}>
          {session.displayName}
        </div>
        <div className="field">
          <label>Active role</label>
          <select
            value={session.activeRole}
            onChange={e => switchRole(e.target.value as Role)}
          >
            {session.roles.map(r => (
              <option key={r} value={r}>{roleLabel(r)}</option>
            ))}
          </select>
        </div>
        {nav.map(item => (
          <button
            key={item.id}
            className={`nav-btn ${page === item.id ? 'active' : ''}`}
            onClick={() => setPage(item.id)}
          >
            {item.label}
          </button>
        ))}
        <div style={{ flex: 1 }} />
        <button className="secondary" onClick={logout}>Sign out</button>
      </aside>
      <div className="main">
        <div className="topbar">
          <div>
            <strong>{nav.find(n => n.id === page)?.label}</strong>
            <span className="muted"> · {roleLabel(session.activeRole)}</span>
          </div>
          <div className="muted">
            svc v{bootstrap?.serviceabilityVersion ?? '—'} · net rev {bootstrap?.networkRevision ?? '—'}
          </div>
        </div>
        <div className="content">
          {error && <div className="error-box">{error}</div>}
          {page === 'work' && <WorkPage session={session} bootstrap={bootstrap} />}
          {page === 'request' && <RequestPage session={session} bootstrap={bootstrap} />}
          {page === 'ops' && <OpsPage session={session} bootstrap={bootstrap} />}
          {page === 'admin' && <AdminPage session={session} bootstrap={bootstrap} onRefresh={async () => setBootstrap(await api('/ui/bootstrap'))} />}
          {page === 'sample' && <SamplePage session={session} />}
          {page === 'map' && <MapPage session={session} bootstrap={bootstrap} />}
          {page === 'audit' && <AuditPage session={session} />}
        </div>
      </div>
    </div>
  )
}

import { FormEvent, useState } from 'react'

export default function LoginPage({
  onLogin, error, loading,
}: {
  onLogin: (u: string, p: string) => void
  error?: string
  loading?: boolean
}) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')

  function submit(e: FormEvent) {
    e.preventDefault()
    onLogin(username.trim(), password)
  }

  return (
    <div className="login-wrap">
      <form className="card login-card" onSubmit={submit}>
        <h2 style={{ marginTop: 0 }}>Lab Sample Pickup & Delivery</h2>
        <p className="muted">Sign in with your assigned account. The first administrator is created from environment variables on first start.</p>
        {error && <div className="error-box">{error}</div>}
        <div className="field">
          <label>Username</label>
          <input value={username} onChange={e => setUsername(e.target.value)} autoComplete="username" required />
        </div>
        <div className="field">
          <label>Password</label>
          <input type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required />
