import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

function isoPlusHours(h: number) {
  return new Date(Date.now() + h * 3600_000).toISOString()
}

export default function RequestPage({ session, bootstrap }: { session: AuthSession; bootstrap?: any }) {
  const sampleTypes = bootstrap?.sampleTypes || []
  const [form, setForm] = useState({
    originType: 'home',
    latitude: 12.9716,
    longitude: 77.5946,
    sampleTypeId: '',
    earliestCollectionAt: isoPlusHours(1),
    latestCollectionAt: isoPlusHours(4),
    deliveryDeadline: isoPlusHours(12),
  })
  const [svc, setSvc] = useState<any>(null)
  const [created, setCreated] = useState<any>(null)
  const [items, setItems] = useState<any[]>([])
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')

  useEffect(() => {
    if (sampleTypes.length && !form.sampleTypeId) {
      setForm(f => ({ ...f, sampleTypeId: sampleTypes[0].id }))
    }
  }, [sampleTypes])

  async function loadMine() {
    try {
      const data = await api<any>('/list-role-work', {
        body: { scope: 'current', role: 'requester' },
      })
      setItems(data.items || data.workItems || data.requests || [])
    } catch {
      /* requester may only see requests via ops if dispatcher */
    }
  }

  useEffect(() => { loadMine() }, [session.activeRole])

  async function checkServiceability() {
    setError('')
    setSvc(null)
    try {
      const data = await api('/check-serviceability', {
        body: {
          origin: { latitude: form.latitude, longitude: form.longitude },
          originType: form.originType,
          sampleTypeId: form.sampleTypeId,
          requestedAt: new Date().toISOString(),
          earliestCollectionAt: form.earliestCollectionAt,
          latestCollectionAt: form.latestCollectionAt,
          deliveryDeadline: form.deliveryDeadline,
        },
      })
      setSvc(data)
      setMsg(data.serviceable ? 'Serviceable' : `Not serviceable: ${data.reason || data.reasons}`)
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function createRequest() {
    setError('')
    setCreated(null)
    try {
      const data = await api('/create-collection-request', {
        body: {
          origin: { latitude: form.latitude, longitude: form.longitude },
          originType: form.originType,
          sampleTypeId: form.sampleTypeId,
          earliestCollectionAt: form.earliestCollectionAt,
          latestCollectionAt: form.latestCollectionAt,
          deliveryDeadline: form.deliveryDeadline,
          idempotencyKey: uuid(),
        },
      })
      setCreated(data)
      setMsg('Collection request created')
      await loadMine()
    } catch (e: any) {
      setError(e.message)
    }
  }

