import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

export default function OpsPage({ session }: { session: AuthSession; bootstrap?: any }) {
  const [state, setState] = useState<any>(null)
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')
  const [journeyId, setJourneyId] = useState('')
  const [resourceType, setResourceType] = useState('location')
  const [resourceId, setResourceId] = useState('')

  async function load() {
    setError('')
    try {
      const data = await api('/read-operations-state', { body: {} })
      setState(data)
    } catch (e: any) {
      setError(e.message)
    }
  }

  useEffect(() => { load() }, [session.activeRole])

  async function cancelJourney() {
    try {
      await api('/cancel-journey', { body: { journeyId, expectedPlanVersion: 0 } })
      setMsg('Journey cancelled')
      await load()
    } catch (e: any) { setError(e.message) }
  }

  async function rerouteJourney() {
    try {
      const data = await api('/reroute-journey', { body: { journeyId, expectedPlanVersion: 0 } })
      setMsg(`Rerouted → ${data.journeyId}`)
      await load()
    } catch (e: any) { setError(e.message) }
  }

  async function reportDisruption() {
    try {
      const data = await api('/report-disruption', {
        body: {
          resourceType,
          resourceId,
          reason: 'manual_ops_disruption',
          occurredAt: new Date().toISOString(),
          idempotencyKey: uuid(),
        },
      })
      setMsg(`Disruption ${data.disruptionId} · replan ${data.replanStatus}`)
      await load()
    } catch (e: any) { setError(e.message) }
  }

  return (
    <div className="grid">
      <div className="card">
        <div className="row" style={{ alignItems: 'center' }}>
          <h3 style={{ margin: 0, flex: 2 }}>Operations monitor</h3>
          <button className="secondary" onClick={load}>Refresh</button>
        </div>
        {error && <div className="error-box">{error}</div>}
        {msg && <div className="success-box">{msg}</div>}
        <div className="row" style={{ marginTop: '1rem' }}>
          <div className="field">
            <label>Journey ID</label>
            <input value={journeyId} onChange={e => setJourneyId(e.target.value)} placeholder="uuid" />
          </div>
          <div className="field" style={{ display: 'flex', gap: 8, alignItems: 'end' }}>
            <button className="secondary" onClick={rerouteJourney}>Reroute</button>
            <button className="danger" onClick={cancelJourney}>Cancel</button>
          </div>
        </div>
        <div className="row">
          <div className="field">
            <label>Disruption resource type</label>
            <select value={resourceType} onChange={e => setResourceType(e.target.value)}>
              <option value="location">location</option>
              <option value="connection">connection</option>
              <option value="worker">worker</option>
              <option value="route">route</option>
              <option value="laboratory">laboratory</option>
            </select>
          </div>
          <div className="field">
            <label>Resource ID</label>
            <input value={resourceId} onChange={e => setResourceId(e.target.value)} />
          </div>
          <div className="field" style={{ display: 'flex', alignItems: 'end' }}>
            <button onClick={reportDisruption}>Report disruption</button>
          </div>
        </div>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Active samples</h3>
        <table className="table">
          <thead>
            <tr>
              <th>Sample</th>
              <th>Status</th>
              <th>Holder</th>
              <th>Location</th>
              <th>Stale</th>
            </tr>
          </thead>
          <tbody>
            {(state?.samples || []).length === 0 && (
              <tr><td colSpan={5} className="muted">No active samples</td></tr>
            )}
            {(state?.samples || []).map((s: any) => (
              <tr key={s.sampleId || s.id}>
                <td className="muted" style={{ fontSize: '0.8rem' }}>{s.sampleId || s.id}</td>
                <td><span className="badge">{s.status}</span></td>
                <td>{s.currentHolderName || s.currentHolderId || '—'}</td>
                <td className="muted">
                  {s.lastKnownLocation
                    ? `${s.lastKnownLocation.latitude?.toFixed?.(4)}, ${s.lastKnownLocation.longitude?.toFixed?.(4)}`
                    : '—'}
                </td>
                <td>{s.locationStale ? <span className="badge warn">stale</span> : <span className="badge ok">fresh</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Workers</h3>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Roles</th><th>Available</th><th>Location</th></tr>
          </thead>
          <tbody>
            {(state?.workers || []).map((w: any) => (
              <tr key={w.userId || w.id}>
                <td>{w.displayName || w.username}</td>
                <td className="muted">{(w.roles || []).join(', ')}</td>
                <td>{w.available ? 'yes' : 'no'}</td>
                <td className="muted">
                  {w.location ? `${w.location.latitude?.toFixed?.(4)}, ${w.location.longitude?.toFixed?.(4)}` : '—'}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Exceptions</h3>
        <table className="table">
          <thead>
            <tr><th>Sample</th><th>Reason</th><th>At</th></tr>
          </thead>
          <tbody>
            {(state?.exceptions || []).length === 0 && (
              <tr><td colSpan={3} className="muted">None</td></tr>
            )}
            {(state?.exceptions || []).map((ex: any, i: number) => (
              <tr key={i}>
                <td className="muted">{ex.sampleId}</td>
                <td>{ex.reason || JSON.stringify(ex.exception || ex)}</td>
                <td className="muted">{ex.at || ex.updatedAt || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

