import { useState } from 'react'
import { api, AuthSession } from '../api'

export default function SamplePage({ session }: { session: AuthSession }) {
  const [sampleId, setSampleId] = useState('')
  const [state, setState] = useState<any>(null)
  const [lifecycle, setLifecycle] = useState<any>(null)
  const [plan, setPlan] = useState<any>(null)
  const [error, setError] = useState('')

  async function load() {
    setError('')
    setState(null)
    setLifecycle(null)
    setPlan(null)
    try {
      const st = await api(`/read-sample-state/${encodeURIComponent(sampleId)}`)
      setState(st)
      try {
        const lc = await api('/read-sample-lifecycle', { body: { sampleId } })
        setLifecycle(lc)
      } catch { /* optional */ }
      if (st?.activeJourneyId || st?.journeyId) {
        try {
          const p = await api('/read-journey-plan', {
            body: { journeyId: st.activeJourneyId || st.journeyId },
          })
          setPlan(p)
        } catch { /* optional */ }
      }
    } catch (e: any) {
      setError(e.message)
    }
  }

  return (
    <div className="grid">
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Sample lookup</h3>
        <div className="row">
          <div className="field">
            <label>Sample ID</label>
            <input value={sampleId} onChange={e => setSampleId(e.target.value)} placeholder="uuid" />
          </div>
          <div className="field" style={{ display: 'flex', alignItems: 'end' }}>
            <button onClick={load}>Load</button>
          </div>
        </div>
        {error && <div className="error-box">{error}</div>}
      </div>

      {state && (
        <div className="card">
          <h3 style={{ marginTop: 0 }}>Current state</h3>
          <div className="row">
            <div><span className="muted">Status</span><div><span className="badge">{state.status}</span></div></div>
            <div><span className="muted">Holder</span><div>{state.currentHolderName || state.currentHolderId || '—'}</div></div>
            <div><span className="muted">Sealed</span><div>{state.sealed ? 'yes' : 'no'}</div></div>
            <div><span className="muted">Location stale</span><div>{state.locationStale ? 'yes' : 'no'}</div></div>
          </div>
          <pre className="json">{JSON.stringify(state, null, 2)}</pre>
        </div>
      )}

      {lifecycle && (
        <div className="card">
          <h3 style={{ marginTop: 0 }}>Lifecycle timeline</h3>
          <div className="timeline">
            {(lifecycle.events || lifecycle.timeline || []).map((ev: any, i: number) => (
              <div className="timeline-item" key={i}>
                <div><strong>{ev.type || ev.action || ev.status}</strong> <span className="muted">{ev.at || ev.occurredAt}</span></div>
                <div className="muted">{ev.summary || ev.message || JSON.stringify(ev.details || {})}</div>
              </div>
            ))}
          </div>
          {!(lifecycle.events || lifecycle.timeline)?.length && (
            <pre className="json">{JSON.stringify(lifecycle, null, 2)}</pre>
          )}
        </div>
      )}

      {plan && (
        <div className="card">
          <h3 style={{ marginTop: 0 }}>Journey plan</h3>
          <pre className="json">{JSON.stringify(plan, null, 2)}</pre>
        </div>
      )}
      <div className="muted">Role: {session.activeRole}</div>
    </div>
  )
}

