import { useEffect, useRef, useState } from 'react'
import maplibregl from 'maplibre-gl'
import { Protocol } from 'pmtiles'
import { api, AuthSession } from '../api'
import 'maplibre-gl/dist/maplibre-gl.css'

let protocolRegistered = false

export default function MapPage({ bootstrap }: { session: AuthSession; bootstrap?: any }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const [error, setError] = useState('')
  const [ops, setOps] = useState<any>(null)

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const data = await api('/read-operations-state', { body: {} })
        if (!cancelled) setOps(data)
      } catch {
        /* requester may lack access; still show map */
      }
    })()
    return () => { cancelled = true }
  }, [])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    try {
      if (!protocolRegistered) {
        const protocol = new Protocol()
        maplibregl.addProtocol('pmtiles', protocol.tile)
        protocolRegistered = true
      }
      const map = new maplibregl.Map({
        container: ref.current,
        style: '/map/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
      })
      map.addControl(new maplibregl.NavigationControl(), 'top-right')
      mapRef.current = map
      map.on('error', (e) => {
        console.warn('map error', e)
      })
      return () => {
        map.remove()
        mapRef.current = null
      }
    } catch (e: any) {
      setError(e.message || 'Map failed to load')
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !ops) return

    const draw = () => {
      const locs = ops.locations || bootstrap?.locations || []
      locs.forEach((l: any) => {
        if (l.latitude == null && !l.coordinate) return
        const lng = l.longitude ?? l.coordinate?.longitude
        const lat = l.latitude ?? l.coordinate?.latitude
        if (lng == null || lat == null) return
        const el = document.createElement('div')
        el.style.width = '12px'
        el.style.height = '12px'
        el.style.borderRadius = '50%'
        el.style.background = l.fnLaboratory ? '#22c55e' : l.fnHub ? '#3b82f6' : '#f59e0b'
        el.style.border = '2px solid white'
        new maplibregl.Marker({ element: el })
          .setLngLat([lng, lat])
          .setPopup(new maplibregl.Popup().setText(l.name || l.id))
          .addTo(map)
      })
      ;(ops.workers || []).forEach((w: any) => {
        const loc = w.location || w.lastKnownLocation
        if (!loc) return
        const el = document.createElement('div')
        el.style.width = '10px'
        el.style.height = '10px'
        el.style.borderRadius = '2px'
        el.style.background = '#a78bfa'
        el.style.border = '1px solid white'
        new maplibregl.Marker({ element: el })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(new maplibregl.Popup().setText(w.displayName || w.username || 'worker'))
          .addTo(map)
      })
      ;(ops.samples || []).forEach((s: any) => {
        const loc = s.lastKnownLocation || s.location
        if (!loc) return
        const el = document.createElement('div')
        el.style.width = '8px'
        el.style.height = '8px'
        el.style.borderRadius = '1px'
        el.style.background = s.locationStale ? '#ef4444' : '#38bdf8'
        new maplibregl.Marker({ element: el })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(new maplibregl.Popup().setText(`Sample ${s.sampleId || s.id}`))
          .addTo(map)
      })
    }

    if (map.isStyleLoaded()) draw()
    else map.on('load', draw)
  }, [ops, bootstrap])

  return (
    <div className="grid">
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Live network map</h3>
        <p className="muted">
          Nodes (amber), hubs (blue), laboratories (green), workers (purple), samples (cyan / red if stale).
        </p>
        {error && <div className="error-box">{error}</div>}
        <div className="map-wrap" ref={ref} />
      </div>
    </div>
  )
}

