import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

function isoPlusHours(h: number) {
  return new Date(Date.now() + h * 3600_000).toISOString()
}

export default function RequestPage({ session, bootstrap }: { session: AuthSession; bootstrap?: any }) {
  const sampleTypes = bootstrap?.sampleTypes || []
  const [form, setForm] = useState({
    originType: 'home',
    latitude: 12.9716,
    longitude: 77.5946,
    sampleTypeId: '',
    earliestCollectionAt: isoPlusHours(1),
    latestCollectionAt: isoPlusHours(4),
    deliveryDeadline: isoPlusHours(12),
  })
  const [svc, setSvc] = useState<any>(null)
  const [created, setCreated] = useState<any>(null)
  const [items, setItems] = useState<any[]>([])
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')

  useEffect(() => {
    if (sampleTypes.length && !form.sampleTypeId) {
      setForm(f => ({ ...f, sampleTypeId: sampleTypes[0].id }))
    }
  }, [sampleTypes])

  async function loadMine() {
    try {
      const data = await api<any>('/list-role-work', {
        body: { scope: 'current', role: 'requester' },
      })
      setItems(data.items || data.workItems || data.requests || [])
    } catch {
      /* requester may only see requests via ops if dispatcher */
    }
  }

  useEffect(() => { loadMine() }, [session.activeRole])

  async function checkServiceability() {
    setError('')
    setSvc(null)
    try {
      const data = await api('/check-serviceability', {
        body: {
          origin: { latitude: form.latitude, longitude: form.longitude },
          originType: form.originType,
          sampleTypeId: form.sampleTypeId,
          requestedAt: new Date().toISOString(),
          earliestCollectionAt: form.earliestCollectionAt,
          latestCollectionAt: form.latestCollectionAt,
          deliveryDeadline: form.deliveryDeadline,
        },
      })
      setSvc(data)
      setMsg(data.serviceable ? 'Serviceable' : `Not serviceable: ${data.reason || data.reasons}`)
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function createRequest() {
    setError('')
    setCreated(null)
    try {
      const data = await api('/create-collection-request', {
        body: {
          origin: { latitude: form.latitude, longitude: form.longitude },
          originType: form.originType,
          sampleTypeId: form.sampleTypeId,
          earliestCollectionAt: form.earliestCollectionAt,
          latestCollectionAt: form.latestCollectionAt,
          deliveryDeadline: form.deliveryDeadline,
          idempotencyKey: uuid(),
        },
      })
      setCreated(data)
      setMsg('Collection request created')
      await loadMine()
    } catch (e: any) {
      setError(e.message)
    }
  }

  return (
    <div className="grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Serviceability & request</h3>
        {error && <div className="error-box">{error}</div>}
        {msg && <div className="success-box">{msg}</div>}
        <div className="field">
          <label>Origin type</label>
          <select value={form.originType} onChange={e => setForm(f => ({ ...f, originType: e.target.value }))}>
            <option value="home">Home</option>
            <option value="clinic">Clinic</option>
            <option value="node">Network node</option>
          </select>
        </div>
        <div className="row">
          <div className="field">
            <label>Latitude</label>
            <input type="number" step="0.0001" value={form.latitude}
              onChange={e => setForm(f => ({ ...f, latitude: Number(e.target.value) }))} />
          </div>
          <div className="field">
            <label>Longitude</label>
            <input type="number" step="0.0001" value={form.longitude}
              onChange={e => setForm(f => ({ ...f, longitude: Number(e.target.value) }))} />
          </div>
        </div>
        <div className="field">
          <label>Sample type</label>
          <select value={form.sampleTypeId} onChange={e => setForm(f => ({ ...f, sampleTypeId: e.target.value }))}>
            {sampleTypes.map((st: any) => (
              <option key={st.id} value={st.id}>{st.name}</option>
            ))}
          </select>
        </div>
        <div className="field">
          <label>Earliest collection</label>
          <input type="datetime-local"
            value={form.earliestCollectionAt.slice(0, 16)}
            onChange={e => setForm(f => ({ ...f, earliestCollectionAt: new Date(e.target.value).toISOString() }))} />
        </div>
        <div className="field">
          <label>Latest collection</label>
          <input type="datetime-local"
            value={form.latestCollectionAt.slice(0, 16)}
            onChange={e => setForm(f => ({ ...f, latestCollectionAt: new Date(e.target.value).toISOString() }))} />
        </div>
        <div className="field">
          <label>Delivery deadline</label>
          <input type="datetime-local"
            value={form.deliveryDeadline.slice(0, 16)}
            onChange={e => setForm(f => ({ ...f, deliveryDeadline: new Date(e.target.value).toISOString() }))} />
        </div>
        <div className="row">
          <button className="secondary" onClick={checkServiceability}>Check serviceability</button>
          <button onClick={createRequest}>Create request</button>
        </div>
        {svc && <pre className="json">{JSON.stringify(svc, null, 2)}</pre>}
        {created && <pre className="json">{JSON.stringify(created, null, 2)}</pre>}
      </div>
      <div className="card">
        <h3 style={{ marginTop: 0 }}>My requests / work</h3>
        <table className="table">
          <thead>
            <tr><th>ID</th><th>Status</th><th>Type</th></tr>
          </thead>
          <tbody>
            {items.length === 0 && <tr><td colSpan={3} className="muted">No items</td></tr>}
            {items.map((it: any, i: number) => (
              <tr key={it.requestId || it.sampleId || i}>
                <td className="muted" style={{ fontSize: '0.8rem' }}>{it.requestId || it.sampleId || it.id}</td>
                <td>{it.status}</td>
                <td>{it.sampleTypeName || it.kind || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { api, AuthSession, uuid } from '../api'

export default function OpsPage({ session }: { session: AuthSession; bootstrap?: any }) {
  const [state, setState] = useState<any>(null)
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')
  const [journeyId, setJourneyId] = useState('')
  const [resourceType, setResourceType] = useState('location')
  const [resourceId, setResourceId] = useState('')

  async function load() {
    setError('')
    try {
      const data = await api('/read-operations-state', { body: {} })
      setState(data)
    } catch (e: any) {
      setError(e.message)
    }
  }

  useEffect(() => { load() }, [session.activeRole])

  async function cancelJourney() {
    try {
      await api('/cancel-journey', { body: { journeyId, expectedPlanVersion: 0 } })
      setMsg('Journey cancelled')
      await load()
    } catch (e: any) { setError(e.message) }
  }

  async function rerouteJourney() {
    try {
      const data = await api('/reroute-journey', { body: { journeyId, expectedPlanVersion: 0 } })
      setMsg(`Rerouted → ${data.journeyId}`)
      await load()
