import { useState } from 'react'
import { api, AuthSession, uuid } from '../api'

const ALL_ROLES = [
  'requester', 'collection_professional', 'delivery_partner',
  'node_handler', 'laboratory_team', 'dispatcher', 'administrator',
]

export default function AdminPage({
  session, bootstrap, onRefresh,
}: {
  session: AuthSession
  bootstrap?: any
  onRefresh?: () => void
}) {
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')
  const [userForm, setUserForm] = useState({
    username: '', password: '', displayName: '', roles: ['requester'] as string[],
    certifications: [] as string[], assignedLocationIds: [] as string[],
  })
  const [locForm, setLocForm] = useState({
    name: '', latitude: 12.97, longitude: 77.59, coverageKm: 5,
    fnCollectionPoint: true, fnTransferPoint: false, fnHub: false, fnLaboratory: false,
    capacityUnits: 20, cooledCapacityUnits: 10, handlingMinutes: 10,
  })
  const [connForm, setConnForm] = useState({
    fromLocationId: '', toLocationId: '', travelMinutes: 30,
    capacityUnits: 10, cooledCapacityUnits: 5, cooled: true,
  })
  const locations = bootstrap?.locations || []
  const sampleTypes = bootstrap?.sampleTypes || []

  async function createUser() {
    setError('')
    try {
      const data = await api('/create-user', {
        body: { ...userForm, idempotencyKey: uuid() },
      })
      setMsg(`User created: ${data.userId || data.username}`)
      onRefresh?.()
    } catch (e: any) { setError(e.message) }
  }

  async function createLocation() {
    setError('')
    try {
      const data = await api('/create-location', {
        body: {
          name: locForm.name,
          coordinate: { latitude: locForm.latitude, longitude: locForm.longitude },
          coverageKm: locForm.coverageKm,
          functions: {
            collectionPoint: locForm.fnCollectionPoint,
            transferPoint: locForm.fnTransferPoint,
            hub: locForm.fnHub,
            laboratory: locForm.fnLaboratory,
          },
          capacityUnits: locForm.capacityUnits,
          cooledCapacityUnits: locForm.cooledCapacityUnits,
          handlingMinutes: locForm.handlingMinutes,
          active: true,
          idempotencyKey: uuid(),
        },
      })
      setMsg(`Location created: ${data.locationId || data.id}`)
      onRefresh?.()
    } catch (e: any) { setError(e.message) }
  }

  async function createConnection() {
    setError('')
    try {
      const data = await api('/create-connection', {
        body: {
          ...connForm,
          active: true,
          idempotencyKey: uuid(),
        },
      })
      setMsg(`Connection created: ${data.connectionId || data.id}`)
      onRefresh?.()
    } catch (e: any) { setError(e.message) }
  }

  async function configureLab(locationId: string, sampleTypeIds: string[]) {
    try {
      await api('/configure-laboratory-acceptance', {
        body: { locationId, acceptedSampleTypeIds: sampleTypeIds },
      })
      setMsg('Laboratory acceptance updated')
      onRefresh?.()
    } catch (e: any) { setError(e.message) }
  }

  function toggleRole(r: string) {
    setUserForm(f => ({
      ...f,
      roles: f.roles.includes(r) ? f.roles.filter(x => x !== r) : [...f.roles, r],
    }))
  }

  return (
    <div className="grid">
      {error && <div className="error-box">{error}</div>}
      {msg && <div className="success-box">{msg}</div>}

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Create user</h3>
        <div className="row">
          <div className="field"><label>Username</label>
            <input value={userForm.username} onChange={e => setUserForm(f => ({ ...f, username: e.target.value }))} /></div>
          <div className="field"><label>Password</label>
            <input type="password" value={userForm.password} onChange={e => setUserForm(f => ({ ...f, password: e.target.value }))} /></div>
          <div className="field"><label>Display name</label>
            <input value={userForm.displayName} onChange={e => setUserForm(f => ({ ...f, displayName: e.target.value }))} /></div>
        </div>
        <div className="field">
          <label>Roles</label>
          <div className="row">
            {ALL_ROLES.map(r => (
              <label key={r} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                <input type="checkbox" checked={userForm.roles.includes(r)} onChange={() => toggleRole(r)} />
                {r}
              </label>
            ))}
          </div>
        </div>
        <div className="field">
          <label>Certifications (comma-separated sample type names/ids)</label>
          <input
            value={userForm.certifications.join(',')}
            onChange={e => setUserForm(f => ({
              ...f,
              certifications: e.target.value.split(',').map(s => s.trim()).filter(Boolean),
            }))}
          />
        </div>
        <div className="field">
          <label>Assigned location IDs (comma-separated)</label>
          <input
            value={userForm.assignedLocationIds.join(',')}
            onChange={e => setUserForm(f => ({
              ...f,
              assignedLocationIds: e.target.value.split(',').map(s => s.trim()).filter(Boolean),
            }))}
          />
        </div>
        <button onClick={createUser}>Create user</button>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Create location</h3>
        <div className="row">
          <div className="field"><label>Name</label>
            <input value={locForm.name} onChange={e => setLocForm(f => ({ ...f, name: e.target.value }))} /></div>
          <div className="field"><label>Lat</label>
            <input type="number" step="0.0001" value={locForm.latitude}
              onChange={e => setLocForm(f => ({ ...f, latitude: Number(e.target.value) }))} /></div>
          <div className="field"><label>Lng</label>
            <input type="number" step="0.0001" value={locForm.longitude}
              onChange={e => setLocForm(f => ({ ...f, longitude: Number(e.target.value) }))} /></div>
        </div>
        <div className="row">
          {(['fnCollectionPoint', 'fnTransferPoint', 'fnHub', 'fnLaboratory'] as const).map(k => (
            <label key={k} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
              <input type="checkbox" checked={(locForm as any)[k]}
                onChange={e => setLocForm(f => ({ ...f, [k]: e.target.checked }))} />
              {k.replace('fn', '')}
            </label>
          ))}
        </div>
        <div className="row">
          <div className="field"><label>Capacity</label>
            <input type="number" value={locForm.capacityUnits}
              onChange={e => setLocForm(f => ({ ...f, capacityUnits: Number(e.target.value) }))} /></div>
          <div className="field"><label>Cooled capacity</label>
            <input type="number" value={locForm.cooledCapacityUnits}
              onChange={e => setLocForm(f => ({ ...f, cooledCapacityUnits: Number(e.target.value) }))} /></div>
          <div className="field"><label>Coverage km</label>
            <input type="number" value={locForm.coverageKm}
              onChange={e => setLocForm(f => ({ ...f, coverageKm: Number(e.target.value) }))} /></div>
        </div>
        <button onClick={createLocation}>Create location</button>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Create connection</h3>
        <div className="row">
          <div className="field">
            <label>From</label>
            <select value={connForm.fromLocationId}
              onChange={e => setConnForm(f => ({ ...f, fromLocationId: e.target.value }))}>
              <option value="">—</option>
              {locations.map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}
            </select>
          </div>
          <div className="field">
            <label>To</label>
            <select value={connForm.toLocationId}
              onChange={e => setConnForm(f => ({ ...f, toLocationId: e.target.value }))}>
              <option value="">—</option>
              {locations.map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}
            </select>
          </div>
          <div className="field">
            <label>Travel minutes</label>
            <input type="number" value={connForm.travelMinutes}
              onChange={e => setConnForm(f => ({ ...f, travelMinutes: Number(e.target.value) }))} />
          </div>
        </div>
        <button onClick={createConnection}>Create connection</button>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Locations</h3>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Functions</th><th>Capacity</th><th>Active</th><th>Lab types</th></tr>
          </thead>
          <tbody>
            {locations.map((l: any) => (
              <tr key={l.id}>
                <td>{l.name}<div className="muted" style={{ fontSize: '0.75rem' }}>{l.id}</div></td>
                <td className="muted">
                  {[l.fnCollectionPoint && 'collection', l.fnTransferPoint && 'transfer', l.fnHub && 'hub', l.fnLaboratory && 'lab']
                    .filter(Boolean).join(', ')}
                </td>
                <td>{l.capacityUnits}/{l.cooledCapacityUnits} cooled</td>
                <td>{l.active ? 'yes' : 'no'}</td>
                <td>
                  {l.fnLaboratory && (
                    <button className="secondary" style={{ fontSize: '0.8rem' }}
                      onClick={() => configureLab(l.id, sampleTypes.map((s: any) => s.id))}>
                      Accept all types
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Sample types</h3>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Cooled</th><th>Batching</th><th>Container</th></tr>
          </thead>
          <tbody>
            {sampleTypes.map((st: any) => (
              <tr key={st.id}>
                <td>{st.name}</td>
                <td>{st.requiresCooled ? 'yes' : 'no'}</td>
                <td>{st.batchingAllowed === false ? 'no' : 'yes'}</td>
                <td className="muted">{st.containerType || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="muted">Signed in as {session.username}</div>
    </div>
  )
}

import { useState } from 'react'
import { api, AuthSession } from '../api'

export default function SamplePage({ session }: { session: AuthSession }) {
  const [sampleId, setSampleId] = useState('')
  const [state, setState] = useState<any>(null)
  const [lifecycle, setLifecycle] = useState<any>(null)
  const [plan, setPlan] = useState<any>(null)
  const [error, setError] = useState('')

  async function load() {
    setError('')
    setState(null)
    setLifecycle(null)
    setPlan(null)
    try {
      const st = await api(`/read-sample-state/${encodeURIComponent(sampleId)}`)
      setState(st)
      try {
        const lc = await api('/read-sample-lifecycle', { body: { sampleId } })
        setLifecycle(lc)
      } catch { /* optional */ }
      if (st?.activeJourneyId || st?.journeyId) {
        try {
          const p = await api('/read-journey-plan', {
            body: { journeyId: st.activeJourneyId || st.journeyId },
          })
          setPlan(p)
        } catch { /* optional */ }
      }
    } catch (e: any) {
      setError(e.message)
    }
  }

  return (
    <div className="grid">
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Sample lookup</h3>
        <div className="row">
          <div className="field">
            <label>Sample ID</label>
            <input value={sampleId} onChange={e => setSampleId(e.target.value)} placeholder="uuid" />
          </div>
          <div className="field" style={{ display: 'flex', alignItems: 'end' }}>
            <button onClick={load}>Load</button>
          </div>
        </div>
        {error && <div className="error-box">{error}</div>}
      </div>

      {state && (
        <div className="card">
          <h3 style={{ marginTop: 0 }}>Current state</h3>
          <div className="row">
            <div><span className="muted">Status</span><div><span className="badge">{state.status}</span></div></div>
            <div><span className="muted">Holder</span><div>{state.currentHolderName || state.currentHolderId || '—'}</div></div>
            <div><span className="muted">Sealed</span><div>{state.sealed ? 'yes' : 'no'}</div></div>
            <div><span className="muted">Location stale</span><div>{state.locationStale ? 'yes' : 'no'}</div></div>
          </div>
          <pre className="json">{JSON.stringify(state, null, 2)}</pre>
        </div>
      )}

      {lifecycle && (
        <div className="card">
          <h3 style={{ marginTop: 0 }}>Lifecycle timeline</h3>
          <div className="timeline">
            {(lifecycle.events || lifecycle.timeline || []).map((ev: any, i: number) => (
              <div className="timeline-item" key={i}>
                <div><strong>{ev.type || ev.action || ev.status}</strong> <span className="muted">{ev.at || ev.occurredAt}</span></div>
                <div className="muted">{ev.summary || ev.message || JSON.stringify(ev.details || {})}</div>
              </div>
            ))}
          </div>
          {!(lifecycle.events || lifecycle.timeline)?.length && (
            <pre className="json">{JSON.stringify(lifecycle, null, 2)}</pre>
          )}
        </div>
      )}

      {plan && (
        <div className="card">
          <h3 style={{ marginTop: 0 }}>Journey plan</h3>
          <pre className="json">{JSON.stringify(plan, null, 2)}</pre>
        </div>
      )}
      <div className="muted">Role: {session.activeRole}</div>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import maplibregl from 'maplibre-gl'
import { Protocol } from 'pmtiles'
import { api, AuthSession } from '../api'
import 'maplibre-gl/dist/maplibre-gl.css'

let protocolRegistered = false

export default function MapPage({ bootstrap }: { session: AuthSession; bootstrap?: any }) {
  const ref = useRef<HTMLDivElement>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const [error, setError] = useState('')
  const [ops, setOps] = useState<any>(null)

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const data = await api('/read-operations-state', { body: {} })
        if (!cancelled) setOps(data)
      } catch {
        /* requester may lack access; still show map */
      }
    })()
    return () => { cancelled = true }
  }, [])

  useEffect(() => {
    if (!ref.current || mapRef.current) return
    try {
      if (!protocolRegistered) {
        const protocol = new Protocol()
        maplibregl.addProtocol('pmtiles', protocol.tile)
        protocolRegistered = true
      }
      const map = new maplibregl.Map({
        container: ref.current,
        style: '/map/style.json',
        center: [77.5946, 12.9716],
        zoom: 11,
      })
      map.addControl(new maplibregl.NavigationControl(), 'top-right')
      mapRef.current = map
      map.on('error', (e) => {
        console.warn('map error', e)
      })
      return () => {
        map.remove()
        mapRef.current = null
      }
    } catch (e: any) {
      setError(e.message || 'Map failed to load')
    }
  }, [])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !ops) return

    const draw = () => {
      const locs = ops.locations || bootstrap?.locations || []
      locs.forEach((l: any) => {
        if (l.latitude == null && !l.coordinate) return
        const lng = l.longitude ?? l.coordinate?.longitude
        const lat = l.latitude ?? l.coordinate?.latitude
        if (lng == null || lat == null) return
        const el = document.createElement('div')
        el.style.width = '12px'
        el.style.height = '12px'
        el.style.borderRadius = '50%'
        el.style.background = l.fnLaboratory ? '#22c55e' : l.fnHub ? '#3b82f6' : '#f59e0b'
        el.style.border = '2px solid white'
        new maplibregl.Marker({ element: el })
          .setLngLat([lng, lat])
          .setPopup(new maplibregl.Popup().setText(l.name || l.id))
          .addTo(map)
      })
      ;(ops.workers || []).forEach((w: any) => {
        const loc = w.location || w.lastKnownLocation
        if (!loc) return
        const el = document.createElement('div')
        el.style.width = '10px'
        el.style.height = '10px'
        el.style.borderRadius = '2px'
        el.style.background = '#a78bfa'
        el.style.border = '1px solid white'
        new maplibregl.Marker({ element: el })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(new maplibregl.Popup().setText(w.displayName || w.username || 'worker'))
          .addTo(map)
      })
      ;(ops.samples || []).forEach((s: any) => {
        const loc = s.lastKnownLocation || s.location
        if (!loc) return
        const el = document.createElement('div')
        el.style.width = '8px'
        el.style.height = '8px'
        el.style.borderRadius = '1px'
        el.style.background = s.locationStale ? '#ef4444' : '#38bdf8'
        new maplibregl.Marker({ element: el })
          .setLngLat([loc.longitude, loc.latitude])
          .setPopup(new maplibregl.Popup().setText(`Sample ${s.sampleId || s.id}`))
          .addTo(map)
      })
    }

    if (map.isStyleLoaded()) draw()
    else map.on('load', draw)
  }, [ops, bootstrap])

  return (
    <div className="grid">
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Live network map</h3>
        <p className="muted">
          Nodes (amber), hubs (blue), laboratories (green), workers (purple), samples (cyan / red if stale).
        </p>
        {error && <div className="error-box">{error}</div>}
        <div className="map-wrap" ref={ref} />
      </div>
    </div>
  )
}

