)

var (
	ErrInvalidCredentials = errors.New("invalid_credentials")
	ErrUnauthorized       = errors.New("unauthorized")
)

type Session struct {
	Token      string
	UserID     uuid.UUID
	ActiveRole string
	User       *models.User
}

type Service struct {
	db *db.DB
}

func New(database *db.DB) *Service {
	return &Service{db: database}
}

func HashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func CheckPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func (s *Service) Authenticate(ctx context.Context, username, password string) (*Session, error) {
	u, err := s.getUserByUsername(ctx, username)
	if err != nil {
		return nil, ErrInvalidCredentials
	}
	if !u.Active || !CheckPassword(u.PasswordHash, password) {
		return nil, ErrInvalidCredentials
	}
	token, err := newToken()
	if err != nil {
		return nil, err
	}
	activeRole := ""
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
	}
	_, err = s.db.PG.Exec(ctx,
		`INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`,
		token, u.ID, activeRole, time.Now().Add(24*time.Hour))
	if err != nil {
		return nil, err
	}
	return &Session{Token: token, UserID: u.ID, ActiveRole: activeRole, User: u}, nil
}

func (s *Service) GetSession(ctx context.Context, token string) (*Session, error) {
	if token == "" {
		return nil, ErrUnauthorized
	}
	var sess Session
	var userID uuid.UUID
	var activeRole string
	err := s.db.PG.QueryRow(ctx,
		`SELECT token, user_id, active_role FROM sessions WHERE token=$1 AND expires_at > NOW()`,
		token).Scan(&sess.Token, &userID, &activeRole)
	if err != nil {
		return nil, ErrUnauthorized
	}
	u, err := s.GetUser(ctx, userID)
	if err != nil || !u.Active {
		return nil, ErrUnauthorized
	}
	sess.UserID = userID
	sess.ActiveRole = activeRole
	sess.User = u
	return &sess, nil
}

func (s *Service) SelectRole(ctx context.Context, token, role string) error {
	_, err := s.db.PG.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2`, role, token)
	return err
}

func (s *Service) DeleteSession(ctx context.Context, token string) error {
	_, err := s.db.PG.Exec(ctx, `DELETE FROM sessions WHERE token=$1`, token)
	return err
}

func (s *Service) GetUser(ctx context.Context, id uuid.UUID) (*models.User, error) {
	row := s.db.PG.QueryRow(ctx, userSelect+` WHERE id=$1`, id)
	return scanUser(row)
}

func (s *Service) getUserByUsername(ctx context.Context, username string) (*models.User, error) {
	row := s.db.PG.QueryRow(ctx, userSelect+` WHERE username=$1`, username)
	return scanUser(row)
}

const userSelect = `
