		       certifications, active, assigned_location_id, available, capacity_units,
		       decline_count, decline_penalty_until, latest_lat, latest_lng, location_recorded_at
		FROM users`

func scanUser(row pgx.Row) (*models.User, error) {
	var u models.User
	var certs []byte
	err := row.Scan(
		&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&u.Roles, &u.Qualifications, &certs, &u.Active, &u.AssignedLocationID,
		&u.Available, &u.CapacityUnits, &u.DeclineCount, &u.DeclinePenaltyUntil,
		&u.LatestLat, &u.LatestLng, &u.LocationRecordedAt,
	)
	if err != nil {
		return nil, err
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	u.Certifications = []models.Certification{}
	if len(certs) > 0 && string(certs) != "null" {
		_ = json.Unmarshal(certs, &u.Certifications)
		if u.Certifications == nil {
			u.Certifications = []models.Certification{}
		}
	}
	return &u, nil
}
