package api

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"labpd/internal/auth"
	"labpd/internal/service"

	"github.com/google/uuid"
	"github.com/gorilla/mux"
	"github.com/gorilla/websocket"
)

type Server struct {
	Svc      *service.Service
	Auth     *auth.Service
	StaticDir string
	MapDir    string
	Router   *mux.Router
	upgrader websocket.Upgrader
}

func New(svc *service.Service, authSvc *auth.Service, staticDir, mapDir string) *Server {
	s := &Server{
		Svc: svc, Auth: authSvc, StaticDir: staticDir, MapDir: mapDir,
		upgrader: websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }},
	}
	s.Router = s.buildRouter()
	return s
}

func (s *Server) buildRouter() *mux.Router {
	r := mux.NewRouter()
	r.HandleFunc("/ready", s.handleReady).Methods("GET")

	api := r.PathPrefix("/api").Subrouter()
	api.HandleFunc("/authenticate-user", s.wrap(s.opAuthenticate, false, 200)).Methods("POST")
	api.HandleFunc("/select-active-role", s.wrap(s.opSelectRole, true, 200)).Methods("POST")
	api.HandleFunc("/create-user", s.wrap(s.opCreateUser, true, 201)).Methods("POST")
	api.HandleFunc("/update-user-access", s.wrap(s.opUpdateUserAccess, true, 200)).Methods("POST")
	api.HandleFunc("/read-user/{userId}", s.handleReadUser).Methods("GET")
	api.HandleFunc("/create-location", s.wrap(s.opCreateLocation, true, 201)).Methods("POST")
	api.HandleFunc("/update-location", s.wrap(s.opUpdateLocation, true, 200)).Methods("POST")
	api.HandleFunc("/set-location-status", s.wrap(s.opSetLocationStatus, true, 200)).Methods("POST")
	api.HandleFunc("/set-location-function-status", s.wrap(s.opSetLocationFunctionStatus, true, 200)).Methods("POST")
	api.HandleFunc("/create-connection", s.wrap(s.opCreateConnection, true, 201)).Methods("POST")
	api.HandleFunc("/set-connection-status", s.wrap(s.opSetConnectionStatus, true, 200)).Methods("POST")
	api.HandleFunc("/configure-capacity", s.wrap(s.opConfigureCapacity, true, 200)).Methods("POST")
	api.HandleFunc("/configure-laboratory-acceptance", s.wrap(s.opConfigureLabAcceptance, true, 200)).Methods("POST")
	api.HandleFunc("/create-sample-type", s.wrap(s.opCreateSampleType, true, 201)).Methods("POST")
	api.HandleFunc("/update-sample-type", s.wrap(s.opUpdateSampleType, true, 200)).Methods("POST")
	api.HandleFunc("/check-serviceability", s.wrap(s.opCheckServiceability, true, 200)).Methods("POST")
	api.HandleFunc("/create-collection-request", s.wrap(s.opCreateCollectionRequest, true, 201)).Methods("POST")
	api.HandleFunc("/ingest-presealed-sample", s.wrap(s.opIngestPresealed, true, 201)).Methods("POST")
	api.HandleFunc("/accept-assignment", s.wrap(s.opAcceptAssignment, true, 201)).Methods("POST")
	api.HandleFunc("/decline-assignment", s.wrap(s.opDeclineAssignment, true, 200)).Methods("POST")
	api.HandleFunc("/collect-and-seal-sample", s.wrap(s.opCollectAndSeal, true, 201)).Methods("POST")
	api.HandleFunc("/initiate-handoff", s.wrap(s.opInitiateHandoff, true, 201)).Methods("POST")
	api.HandleFunc("/confirm-handoff", s.wrap(s.opConfirmHandoff, true, 200)).Methods("POST")
	api.HandleFunc("/update-assignment-progress", s.wrap(s.opUpdateProgress, true, 200)).Methods("POST")
	api.HandleFunc("/confirm-laboratory-receipt", s.wrap(s.opConfirmLabReceipt, true, 201)).Methods("POST")
	api.HandleFunc("/record-laboratory-exception", s.wrap(s.opRecordLabException, true, 201)).Methods("POST")
	api.HandleFunc("/record-handling-checkpoint", s.wrap(s.opRecordCheckpoint, true, 201)).Methods("POST")
	api.HandleFunc("/record-worker-location", s.wrap(s.opRecordWorkerLocation, true, 201)).Methods("POST")
	api.HandleFunc("/set-worker-availability", s.wrap(s.opSetWorkerAvailability, true, 200)).Methods("POST")
	api.HandleFunc("/cancel-journey", s.wrap(s.opCancelJourney, true, 200)).Methods("POST")
	api.HandleFunc("/reroute-journey", s.wrap(s.opRerouteJourney, true, 200)).Methods("POST")
	api.HandleFunc("/edit-active-plan", s.wrap(s.opEditActivePlan, true, 200)).Methods("POST")
	api.HandleFunc("/split-journey", s.wrap(s.opSplitJourney, true, 200)).Methods("POST")
	api.HandleFunc("/merge-journeys", s.wrap(s.opMergeJourneys, true, 200)).Methods("POST")
	api.HandleFunc("/report-disruption", s.wrap(s.opReportDisruption, true, 201)).Methods("POST")
	api.HandleFunc("/list-role-work", s.wrap(s.opListRoleWork, true, 200)).Methods("POST")
	api.HandleFunc("/read-journey-plan", s.wrap(s.opReadJourneyPlan, true, 200)).Methods("POST")
	api.HandleFunc("/read-operations-state", s.wrap(s.opReadOperationsState, true, 200)).Methods("POST")
	api.HandleFunc("/read-sample-lifecycle", s.wrap(s.opReadSampleLifecycle, true, 200)).Methods("POST")
	api.HandleFunc("/read-sample-state/{sampleId}", s.handleReadSampleState).Methods("GET")
	api.HandleFunc("/read-serviceability-snapshot", s.wrap(s.opReadServiceabilitySnapshot, true, 200)).Methods("POST")
	api.HandleFunc("/search-audit-trail", s.wrap(s.opSearchAudit, true, 200)).Methods("POST")
	api.HandleFunc("/ui/bootstrap", s.handleUIBootstrap).Methods("GET")
	api.HandleFunc("/events", s.handleEvents).Methods("GET")

	// Map assets — style.json references /map-assets/ and UI uses /map/
	if s.MapDir != "" {
		mapFS := http.FileServer(http.Dir(s.MapDir))
		r.PathPrefix("/map-assets/").Handler(http.StripPrefix("/map-assets/", mapFS))
		r.PathPrefix("/map/").Handler(http.StripPrefix("/map/", mapFS))
	}
	// SPA static
	if s.StaticDir != "" {
		r.PathPrefix("/assets/").Handler(http.StripPrefix("/assets/", http.FileServer(http.Dir(filepath.Join(s.StaticDir, "assets")))))
		r.PathPrefix("/").HandlerFunc(s.spaHandler)
	}
	return r
}

func (s *Server) spaHandler(w http.ResponseWriter, r *http.Request) {
	path := filepath.Join(s.StaticDir, r.URL.Path)
	if info, err := os.Stat(path); err == nil && !info.IsDir() {
		http.ServeFile(w, r, path)
		return
	}
	http.ServeFile(w, r, filepath.Join(s.StaticDir, "index.html"))
}

type handlerFunc func(ctx context.Context, sess *auth.Session, body map[string]interface{}) (interface{}, *service.AppError)

func (s *Server) wrap(h handlerFunc, needAuth bool, successStatus int) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		ctx := r.Context()
		var sess *auth.Session
		if needAuth {
			var err error
			sess, err = s.sessionFrom(r)
			if err != nil {
				writeErr(w, service.Unauth("unauthorized", "authentication required"))
				return
			}
		}
		body, aerr := readBody(r)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		data, aerr := h(ctx, sess, body)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeJSON(w, successStatus, map[string]interface{}{"data": data})
	}
}

func (s *Server) sessionFrom(r *http.Request) (*auth.Session, error) {
	h := r.Header.Get("Authorization")
	if h == "" {
		return nil, auth.ErrUnauthorized
	}
	token := strings.TrimPrefix(h, "Bearer ")
	token = strings.TrimSpace(token)
	return s.Auth.GetSession(r.Context(), token)
}

func readBody(r *http.Request) (map[string]interface{}, *service.AppError) {
	if r.Body == nil {
		return map[string]interface{}{}, nil
	}
	defer r.Body.Close()
	b, err := io.ReadAll(io.LimitReader(r.Body, 1<<20))
	if err != nil {
		return nil, service.Bad("invalid_json", "cannot read body")
	}
	if len(b) == 0 {
		return map[string]interface{}{}, nil
	}
	var m map[string]interface{}
	dec := json.NewDecoder(strings.NewReader(string(b)))
	dec.UseNumber()
	if err := dec.Decode(&m); err != nil {
		return nil, service.Bad("invalid_json", "invalid json")
	}
	// convert json.Number to float64 for convenience
	normalizeNumbers(m)
	return m, nil
}

func normalizeNumbers(m map[string]interface{}) {
	for k, v := range m {
		switch t := v.(type) {
		case json.Number:
			if i, err := t.Int64(); err == nil {
				m[k] = float64(i)
			} else if f, err := t.Float64(); err == nil {
				m[k] = f
			} else {
				m[k] = t.String()
			}
		case map[string]interface{}:
			normalizeNumbers(t)
		case []interface{}:
			for i, x := range t {
				if n, ok := x.(json.Number); ok {
					if f, err := n.Float64(); err == nil {
						t[i] = f
					}
				} else if mm, ok := x.(map[string]interface{}); ok {
					normalizeNumbers(mm)
				}
			}
		}
	}
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeErr(w http.ResponseWriter, e *service.AppError) {
	if e == nil {
		writeJSON(w, 500, map[string]interface{}{"error": "internal", "code": "internal_error"})
		return
	}
	writeJSON(w, e.HTTPStatus, map[string]interface{}{"error": e.Message, "code": e.Code})
}

func (s *Server) handleReady(w http.ResponseWriter, r *http.Request) {
	if err := s.Svc.DB.Ready(r.Context()); err != nil {
		writeJSON(w, 503, map[string]interface{}{"status": "starting"})
		return
	}
	writeJSON(w, 200, map[string]interface{}{"status": "ready"})
}

func (s *Server) handleReadUser(w http.ResponseWriter, r *http.Request) {
	sess, err := s.sessionFrom(r)
	if err != nil {
		writeErr(w, service.Unauth("unauthorized", "authentication required"))
		return
	}
	uid, err := uuid.Parse(mux.Vars(r)["userId"])
	if err != nil {
		writeErr(w, service.Bad("invalid_json", "invalid userId"))
		return
	}
	data, aerr := s.Svc.ReadUser(r.Context(), sess, uid)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeJSON(w, 200, map[string]interface{}{"data": data})
}

func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	sess, err := s.sessionFrom(r)
	if err != nil {
		writeErr(w, service.Unauth("unauthorized", "authentication required"))
		return
	}
	sid, err := uuid.Parse(mux.Vars(r)["sampleId"])
	if err != nil {
		writeErr(w, service.Bad("invalid_json", "invalid sampleId"))
		return
	}
	data, aerr := s.Svc.ReadSampleState(r.Context(), sess, sid)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeJSON(w, 200, map[string]interface{}{"data": data})
}

func (s *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	sess, err := s.sessionFrom(r)
	if err != nil {
		writeErr(w, service.Unauth("unauthorized", "authentication required"))
		return
	}
	data, aerr := s.Svc.ReadUIBootstrap(r.Context(), sess)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeJSON(w, 200, map[string]interface{}{"data": data})
}

func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	sess, err := s.sessionFrom(r)
	if err != nil {
		writeErr(w, service.Unauth("unauthorized", "authentication required"))
		return
	}
	_ = sess
	// SSE
	flusher, ok := w.(http.Flusher)
	if !ok {
		writeErr(w, service.Internal("streaming not supported"))
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	var lastID int64
	if v := r.URL.Query().Get("after"); v != "" {
		if id, e := parseInt64(v); e == nil {
			lastID = id
		}
	}
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	ctx := r.Context()
	for {
		rows, err := s.Svc.DB.PG.Query(ctx, `
			SELECT id, type, entity_type, entity_id, payload, created_at FROM realtime_events
			WHERE id > $1 ORDER BY id ASC LIMIT 50`, lastID)
		if err == nil {
			for rows.Next() {
				var id int64
				var typ, et, eid string
				var payload []byte
				var at time.Time
				if rows.Scan(&id, &typ, &et, &eid, &payload, &at) != nil {
					continue
				}
				lastID = id
				var p map[string]interface{}
				_ = json.Unmarshal(payload, &p)
				ev := map[string]interface{}{
					"eventId": id, "type": typ, "entityType": et, "entityId": eid,
					"payload": p, "occurredAt": at.UTC().Format(time.RFC3339),
				}
				b, _ := json.Marshal(ev)
				_, _ = w.Write([]byte("data: " + string(b) + "\n\n"))
				flusher.Flush()
			}
			rows.Close()
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func parseInt64(s string) (int64, error) {
	var n int64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, io.EOF
		}
		n = n*10 + int64(c-'0')
	}
	return n, nil
}

