func (s *Service) SearchAuditTrail(ctx context.Context, sess *auth.Session, body map[string]interface{}) (map[string]interface{}, *AppError) {
	if err := requireAdminOrDispatcher(sess); err != nil {
		return nil, err
	}
	filter := bson.M{}
	if v, ok := body["entityType"].(string); ok && v != "" {
		filter["entity_type"] = v
	}
	if v, ok := body["entityId"].(string); ok && v != "" {
		filter["entity_id"] = v
	}
	if v, ok := body["actorId"].(string); ok && v != "" {
		filter["actor_id"] = v
	}
	if v, ok := body["action"].(string); ok && v != "" {
		filter["action"] = v
	}
	if v, ok := body["sampleId"].(string); ok && v != "" {
		// search both sample entity and details
		filter["$or"] = []bson.M{
			{"entity_type": "sample", "entity_id": v},
			{"details.sampleId": v},
		}
	}
	limit := toInt(body["limit"], 50)
	if limit <= 0 || limit > 200 {
		limit = 50
	}
	opts := options.Find().SetSort(bson.D{{Key: "occurred_at", Value: -1}}).SetLimit(int64(limit))
	cur, err := s.DB.MongoDB.Collection("audit_entries").Find(ctx, filter, opts)
	entries := []map[string]interface{}{}
	if err == nil {
		defer cur.Close(ctx)
		for cur.Next(ctx) {
			var doc bson.M
			if cur.Decode(&doc) != nil {
				continue
			}
			entries = append(entries, normalizeAudit(doc))
		}
	}
	// also from PG if mongo empty
	if len(entries) == 0 {
		rows, err := s.DB.PG.Query(ctx, `
			SELECT audit_id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details
			FROM audit_log ORDER BY occurred_at DESC LIMIT $1`, limit)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, actor, role, arole, action, et, eid string
				var success bool
				var at time.Time
				var details []byte
				if rows.Scan(&aid, &actor, &role, &arole, &action, &et, &eid, &success, &at, &details) != nil {
					continue
				}
				var d map[string]interface{}
				_ = json.Unmarshal(details, &d)
				if d == nil {
					d = map[string]interface{}{}
				}
				entries = append(entries, map[string]interface{}{
					"auditId": aid, "audit_id": aid, "actorId": actor, "actor_id": actor,
					"role": role, "actorRole": arole, "action": action,
					"entityType": et, "entity_type": et, "entityId": eid, "entity_id": eid,
					"success": success, "occurredAt": at.UTC().Format(time.RFC3339),
					"occurred_at": at.UTC().Format(time.RFC3339), "details": d,
				})
			}
		}
	}
	return map[string]interface{}{"entries": entries, "count": len(entries)}, nil
}

func normalizeAudit(doc bson.M) map[string]interface{} {
	get := func(keys ...string) interface{} {
		for _, k := range keys {
			if v, ok := doc[k]; ok {
				return v
			}
		}
		return ""
	}
	at := get("occurred_at", "occurredAt")
	var atStr string
	switch t := at.(type) {
	case time.Time:
		atStr = t.UTC().Format(time.RFC3339)
	case string:
		atStr = t
	default:
		atStr = time.Now().UTC().Format(time.RFC3339)
	}
	details, _ := doc["details"].(map[string]interface{})
	if details == nil {
		if d, ok := doc["details"].(bson.M); ok {
			details = map[string]interface{}{}
			for k, v := range d {
				details[k] = v
			}
		} else {
			details = map[string]interface{}{}
		}
	}
	aid := strOf(get("audit_id", "auditId"))
	actor := strOf(get("actor_id", "actorId"))
	et := strOf(get("entity_type", "entityType"))
	eid := strOf(get("entity_id", "entityId"))
	return map[string]interface{}{
		"auditId": aid, "audit_id": aid, "actorId": actor, "actor_id": actor,
		"role": strOf(get("role")), "actorRole": strOf(get("actor_role", "actorRole", "role")),
		"action": strOf(get("action")), "entityType": et, "entity_type": et,
		"entityId": eid, "entity_id": eid,
		"success": toBool(get("success"), true),
		"occurredAt": atStr, "occurred_at": atStr, "details": details,
	}
}

func strOf(v interface{}) string {
	if v == nil {
		return ""
	}
	if s, ok := v.(string); ok {
		return s
	}
	return ""
}
