package service

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
	"sync"
	"time"

	"labpd/internal/auth"
	"labpd/internal/db"
	"labpd/internal/models"
	"labpd/internal/planning"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

type Service struct {
	DB   *db.DB
	Auth *auth.Service
	mu   sync.Mutex
}

func New(database *db.DB, authSvc *auth.Service) *Service {
	return &Service{DB: database, Auth: authSvc}
}

func (s *Service) EnsureBootstrap(ctx context.Context) error {
	if err := s.ensureDefaultSampleTypes(ctx); err != nil {
		return err
	}
	return s.ensureAdmin(ctx)
}

func (s *Service) ensureAdmin(ctx context.Context) error {
	var n int
	if err := s.DB.PG.QueryRow(ctx, `SELECT COUNT(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	hash, err := auth.HashPassword(password)
	if err != nil {
		return err
	}
	_, err = s.DB.PG.Exec(ctx, `
		INSERT INTO users (username, password_hash, email, full_name, roles, qualifications, certifications, active)
		VALUES ($1,$2,$3,$4,$5,'{}','[]',TRUE)`,
		username, hash, "admin@local", "Administrator", []string{models.RoleAdministrator})
	return err
}

func (s *Service) ensureDefaultSampleTypes(ctx context.Context) error {
	defaults := []struct {
		name, qual, container string
		tmin, tmax            float64
		cooled, batch         bool
	}{
		{"Amber", "Amber", "standard", 2, 25, false, true},
		{"Indigo", "Indigo", "standard", 2, 25, false, true},
		{"Frost", "Frost", "cooled", 2, 8, true, true},
		{"Pulse", "Pulse", "standard", 2, 25, false, false},
	}
	var ids = map[string]uuid.UUID{}
	for _, d := range defaults {
		var id uuid.UUID
		err := s.DB.PG.QueryRow(ctx, `SELECT id FROM sample_types WHERE name=$1`, d.name).Scan(&id)
		if err == pgx.ErrNoRows {
			id = uuid.New()
			_, err = s.DB.PG.Exec(ctx, `
				INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
					container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
					requires_cooled_route, batching_allowed)
				VALUES ($1,$2,TRUE,$3,$4,$5,$6,'{}',$7,$8)`,
				id, d.name, d.qual, d.container, d.tmin, d.tmax, d.cooled, d.batch)
			if err != nil {
				return err
			}
		} else if err != nil {
			return err
		}
		ids[d.name] = id
	}
	// Indigo incompatible with Amber
	if amber, ok := ids["Amber"]; ok {
		if indigo, ok2 := ids["Indigo"]; ok2 {
