import { useState } from 'react'
import { api, AuthSession, uuid } from '../api'

const ALL_ROLES = [
  'requester', 'collection_professional', 'delivery_partner',
  'node_handler', 'laboratory_team', 'dispatcher', 'administrator',
]

const SAMPLE_QUALIFICATIONS = ['Amber', 'Indigo', 'Frost', 'Pulse']

export default function AdminPage({
  session, bootstrap, onRefresh,
}: {
  session: AuthSession
  bootstrap?: any
  onRefresh?: () => void
}) {
  const [error, setError] = useState('')
  const [msg, setMsg] = useState('')
  const [userForm, setUserForm] = useState({
    username: '',
    initialPassword: '',
    fullName: '',
    email: '',
    phone: '',
    roles: ['requester'] as string[],
    qualifications: [] as string[],
    assignedLocationId: '',
    active: true,
  })
  const [locForm, setLocForm] = useState({
    name: '',
    latitude: 12.97,
    longitude: 77.59,
    coverageKm: 5,
    handlingMinutes: 10,
    collection_point: true,
    transfer_point: false,
    hub: false,
    laboratory: false,
    capacityUnits: 20,
    cooledCapacityUnits: 10,
  })
  const [connForm, setConnForm] = useState({
    fromLocationId: '',
    toLocationId: '',
    travelMinutes: 30,
    costUnits: 30,
    cooled: true,
    capacityUnits: 10,
    cooledCapacityUnits: 5,
  })

  const locations = (bootstrap?.locations || []).map((l: any) => ({
    ...l,
    id: l.locationId || l.id,
    fnCollectionPoint: l.functions?.collection_point ?? l.fnCollectionPoint,
    fnTransferPoint: l.functions?.transfer_point ?? l.fnTransferPoint,
    fnHub: l.functions?.hub ?? l.fnHub,
    fnLaboratory: l.functions?.laboratory ?? l.fnLaboratory,
  }))
  const sampleTypes = (bootstrap?.sampleTypes || []).map((st: any) => ({
    ...st,
    id: st.sampleTypeId || st.id,
    requiresCooled: st.requiresCooledRoute ?? st.requiresCooled,
  }))

  async function createUser() {
    setError('')
    setMsg('')
    try {
      const body: any = {
        username: userForm.username,
        initialPassword: userForm.initialPassword,
        fullName: userForm.fullName || userForm.username,
        email: userForm.email || `${userForm.username}@example.com`,
        phone: userForm.phone || '',
        roles: userForm.roles,
        qualifications: userForm.qualifications,
        certifications: userForm.qualifications.map(q => ({ code: q, active: true })),
        active: userForm.active,
      }
      if (userForm.assignedLocationId) {
        body.assignedLocationId = userForm.assignedLocationId
      }
      const data = await api('/create-user', { body })
      setMsg(`User created: ${data.userId || data.username}`)
      onRefresh?.()
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function createLocation() {
    setError('')
    setMsg('')
    try {
      const functions: string[] = []
      if (locForm.collection_point) functions.push('collection_point')
      if (locForm.transfer_point) functions.push('transfer_point')
      if (locForm.hub) functions.push('hub')
      if (locForm.laboratory) functions.push('laboratory')
      if (functions.length === 0) {
        setError('Select at least one location function')
        return
      }
      const data = await api('/create-location', {
        body: {
          name: locForm.name,
          coordinate: { latitude: locForm.latitude, longitude: locForm.longitude },
          coverageKm: locForm.coverageKm,
          handlingMinutes: locForm.handlingMinutes,
          functions,
          active: true,
        },
      })
      const locId = data.locationId || data.id
      if (locId) {
        await api('/configure-capacity', {
          body: {
            resourceId: locId,
            capacityUnits: locForm.capacityUnits,
            cooledCapacityUnits: locForm.cooledCapacityUnits,
          },
        })
      }
      setMsg(`Location created: ${locId}`)
      onRefresh?.()
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function createConnection() {
    setError('')
    setMsg('')
    try {
      const data = await api('/create-connection', {
        body: {
          fromLocationId: connForm.fromLocationId,
          toLocationId: connForm.toLocationId,
          travelMinutes: connForm.travelMinutes,
          costUnits: connForm.costUnits || connForm.travelMinutes,
          cooled: connForm.cooled,
          active: true,
        },
      })
      const cid = data.connectionId || data.id
      if (cid) {
        await api('/configure-capacity', {
          body: {
            resourceId: cid,
            capacityUnits: connForm.capacityUnits,
            cooledCapacityUnits: connForm.cooledCapacityUnits,
          },
        })
      }
      setMsg(`Connection created: ${cid}`)
      onRefresh?.()
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function configureLab(locationId: string, sampleTypeIds: string[]) {
    setError('')
    setMsg('')
    try {
      for (const sampleTypeId of sampleTypeIds) {
        await api('/configure-laboratory-acceptance', {
          body: { laboratoryId: locationId, sampleTypeId, accepts: true },
        })
      }
      setMsg('Laboratory acceptance updated')
      onRefresh?.()
    } catch (e: any) {
      setError(e.message)
    }
  }

  function toggleRole(r: string) {
    setUserForm(f => ({
      ...f,
      roles: f.roles.includes(r) ? f.roles.filter(x => x !== r) : [...f.roles, r],
    }))
  }

  function toggleQual(q: string) {
    setUserForm(f => ({
      ...f,
      qualifications: f.qualifications.includes(q)
        ? f.qualifications.filter(x => x !== q)
        : [...f.qualifications, q],
    }))
  }

  return (
    <div className="grid">
      {error && <div className="error-box">{error}</div>}
      {msg && <div className="success-box">{msg}</div>}

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Create user</h3>
        <div className="row">
          <div className="field"><label>Username</label>
            <input value={userForm.username} onChange={e => setUserForm(f => ({ ...f, username: e.target.value }))} /></div>
          <div className="field"><label>Initial password</label>
            <input type="password" value={userForm.initialPassword} onChange={e => setUserForm(f => ({ ...f, initialPassword: e.target.value }))} /></div>
          <div className="field"><label>Full name</label>
            <input value={userForm.fullName} onChange={e => setUserForm(f => ({ ...f, fullName: e.target.value }))} /></div>
        </div>
        <div className="row">
          <div className="field"><label>Email</label>
            <input value={userForm.email} onChange={e => setUserForm(f => ({ ...f, email: e.target.value }))} /></div>
          <div className="field"><label>Phone</label>
            <input value={userForm.phone} onChange={e => setUserForm(f => ({ ...f, phone: e.target.value }))} /></div>
          <div className="field"><label>Assigned location</label>
            <select value={userForm.assignedLocationId} onChange={e => setUserForm(f => ({ ...f, assignedLocationId: e.target.value }))}>
              <option value="">—</option>
              {locations.map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}
            </select>
          </div>
        </div>
        <div className="field">
          <label>Roles</label>
          <div className="row">
            {ALL_ROLES.map(r => (
              <label key={r} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                <input type="checkbox" checked={userForm.roles.includes(r)} onChange={() => toggleRole(r)} />
                {r}
              </label>
            ))}
          </div>
        </div>
        <div className="field">
          <label>Qualifications / certifications</label>
          <div className="row">
            {SAMPLE_QUALIFICATIONS.map(q => (
              <label key={q} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                <input type="checkbox" checked={userForm.qualifications.includes(q)} onChange={() => toggleQual(q)} />
                {q}
              </label>
            ))}
          </div>
        </div>
        <button onClick={createUser}>Create user</button>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Create location</h3>
        <div className="row">
          <div className="field"><label>Name</label>
            <input value={locForm.name} onChange={e => setLocForm(f => ({ ...f, name: e.target.value }))} /></div>
          <div className="field"><label>Lat</label>
            <input type="number" step="0.0001" value={locForm.latitude}
              onChange={e => setLocForm(f => ({ ...f, latitude: Number(e.target.value) }))} /></div>
          <div className="field"><label>Lng</label>
            <input type="number" step="0.0001" value={locForm.longitude}
              onChange={e => setLocForm(f => ({ ...f, longitude: Number(e.target.value) }))} /></div>
        </div>
        <div className="row">
          {(['collection_point', 'transfer_point', 'hub', 'laboratory'] as const).map(k => (
            <label key={k} style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
              <input type="checkbox" checked={(locForm as any)[k]}
                onChange={e => setLocForm(f => ({ ...f, [k]: e.target.checked }))} />
              {k}
            </label>
          ))}
        </div>
        <div className="row">
          <div className="field"><label>Capacity</label>
            <input type="number" value={locForm.capacityUnits}
              onChange={e => setLocForm(f => ({ ...f, capacityUnits: Number(e.target.value) }))} /></div>
          <div className="field"><label>Cooled capacity</label>
            <input type="number" value={locForm.cooledCapacityUnits}
              onChange={e => setLocForm(f => ({ ...f, cooledCapacityUnits: Number(e.target.value) }))} /></div>
          <div className="field"><label>Coverage km</label>
            <input type="number" value={locForm.coverageKm}
              onChange={e => setLocForm(f => ({ ...f, coverageKm: Number(e.target.value) }))} /></div>
          <div className="field"><label>Handling minutes</label>
            <input type="number" value={locForm.handlingMinutes}
              onChange={e => setLocForm(f => ({ ...f, handlingMinutes: Number(e.target.value) }))} /></div>
        </div>
        <button onClick={createLocation}>Create location</button>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Create connection</h3>
        <div className="row">
          <div className="field">
            <label>From</label>
            <select value={connForm.fromLocationId}
              onChange={e => setConnForm(f => ({ ...f, fromLocationId: e.target.value }))}>
              <option value="">—</option>
              {locations.map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}
            </select>
          </div>
          <div className="field">
            <label>To</label>
            <select value={connForm.toLocationId}
              onChange={e => setConnForm(f => ({ ...f, toLocationId: e.target.value }))}>
              <option value="">—</option>
              {locations.map((l: any) => <option key={l.id} value={l.id}>{l.name}</option>)}
            </select>
          </div>
          <div className="field">
            <label>Travel minutes</label>
            <input type="number" value={connForm.travelMinutes}
              onChange={e => setConnForm(f => ({ ...f, travelMinutes: Number(e.target.value), costUnits: Number(e.target.value) }))} />
          </div>
          <div className="field" style={{ display: 'flex', alignItems: 'end' }}>
            <label style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
              <input type="checkbox" checked={connForm.cooled}
                onChange={e => setConnForm(f => ({ ...f, cooled: e.target.checked }))} />
              Cooled
            </label>
          </div>
        </div>
        <button onClick={createConnection}>Create connection</button>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Locations</h3>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Functions</th><th>Active</th><th>Lab types</th></tr>
          </thead>
          <tbody>
            {locations.map((l: any) => (
              <tr key={l.id}>
                <td>{l.name}<div className="muted" style={{ fontSize: '0.75rem' }}>{l.id}</div></td>
                <td className="muted">
                  {[l.fnCollectionPoint && 'collection', l.fnTransferPoint && 'transfer', l.fnHub && 'hub', l.fnLaboratory && 'lab']
                    .filter(Boolean).join(', ')}
                </td>
                <td>{l.active ? 'yes' : 'no'}</td>
                <td>
                  {l.fnLaboratory && (
                    <button className="secondary" style={{ fontSize: '0.8rem' }}
                      onClick={() => configureLab(l.id, sampleTypes.map((s: any) => s.id))}>
                      Accept all types
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>Sample types</h3>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Cooled</th><th>Batching</th><th>Container</th></tr>
          </thead>
          <tbody>
            {sampleTypes.map((st: any) => (
              <tr key={st.id}>
                <td>{st.name}</td>
                <td>{st.requiresCooled ? 'yes' : 'no'}</td>
                <td>{st.batchingAllowed === false ? 'no' : 'yes'}</td>
                <td className="muted">{st.containerType || '—'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="muted">Signed in as {session.username} · {uuid().slice(0, 8)}</div>
    </div>
  )
}

