work = r"""import { useEffect, useState } from "react"
import { api, AuthSession, uuid } from "../api"

export default function WorkPage({ session }: { session: AuthSession; bootstrap?: any }) {
  const [scope, setScope] = useState<"current" | "past">("current")
  const [items, setItems] = useState<any[]>([])
  const [error, setError] = useState("")
  const [msg, setMsg] = useState("")
  const [busy, setBusy] = useState<string | null>(null)
  const [coordinate, setCoordinate] = useState({ latitude: 12.9716, longitude: 77.5946 })
  const [labId, setLabId] = useState("")

  async function load() {
    setError("")
    try {
      const data = await api<any>("/list-role-work", {
        body: { role: session.activeRole },
      })
      const list = scope === "past" ? (data.past || []) : (data.current || [])
      setItems(Array.isArray(list) ? list : [])
    } catch (e: any) {
      setError(e.message)
    }
  }

  useEffect(() => { load() }, [scope, session.activeRole])

  async function accept(assignmentId: string) {
    setBusy(assignmentId)
    setMsg("")
    try {
      await api("/accept-assignment", {
        body: { assignmentId, idempotencyKey: uuid() },
      })
      setMsg("Assignment accepted")
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function decline(assignmentId: string) {
    setBusy(assignmentId)
    try {
      await api("/decline-assignment", {
        body: { assignmentId, reason: "unavailable", idempotencyKey: uuid() },
      })
      setMsg("Assignment declined")
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function collect(assignmentId: string, sampleId: string) {
    setBusy(assignmentId)
    try {
      await api("/collect-and-seal-sample", {
        body: {
          assignmentId,
          sampleId,
          collectedAt: new Date().toISOString(),
          containerType: "standard",
          observedTemperatureC: 4,
          idempotencyKey: uuid(),
        },
      })
      setMsg("Sample collected and sealed")
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function confirmReceipt(sampleId: string) {
    setBusy(sampleId)
    try {
      await api("/confirm-laboratory-receipt", {
        body: {
          sampleId,
          laboratoryId: labId,
          receivedAt: new Date().toISOString(),
          idempotencyKey: uuid(),
        },
      })
      setMsg("Laboratory receipt confirmed")
      await load()
    } catch (e: any) {
      setError(e.message)
    } finally {
      setBusy(null)
    }
  }

  async function updateLoc(assignmentId?: string) {
    try {
      if (!assignmentId) {
        setError("Select an assignment to record location against")
        return
      }
      await api("/record-worker-location", {
        body: {
          assignmentId,
          coordinate,
          sequence: 1,
          recordedAt: new Date().toISOString(),
        },
      })
      setMsg("Location updated")
    } catch (e: any) {
      setError(e.message)
    }
  }

  async function setAvailability(available: boolean) {
    try {
      await api("/set-worker-availability", {
        body: {
          workerId: session.userId,
          available,
          capacityUnits: 5,
        },
      })
      setMsg(available ? "Marked available" : "Marked unavailable")
    } catch (e: any) {
      setError(e.message)
    }
  }

  return (
    <div className="grid">
      <div className="card">
        <div className="tabs">
          <button className={`tab ${scope === "current" ? "active" : ""}`} onClick={() => setScope("current")}>Current</button>
          <button className={`tab ${scope === "past" ? "active" : ""}`} onClick={() => setScope("past")}>Past</button>
        </div>
        {error && <div className="error-box">{error}</div>}
        {msg && <div className="success-box">{msg}</div>}
        <div className="row" style={{ marginTop: "0.75rem" }}>
          <button className="secondary" onClick={() => setAvailability(true)}>Set available</button>
          <button className="secondary" onClick={() => setAvailability(false)}>Set unavailable</button>
          <button className="secondary" onClick={load}>Refresh</button>
        </div>
        <div className="row" style={{ marginTop: "0.75rem" }}>
          <div className="field"><label>Lat</label>
            <input type="number" step="0.0001" value={coordinate.latitude}
              onChange={e => setCoordinate(c => ({ ...c, latitude: Number(e.target.value) }))} /></div>
          <div className="field"><label>Lng</label>
            <input type="number" step="0.0001" value={coordinate.longitude}
              onChange={e => setCoordinate(c => ({ ...c, longitude: Number(e.target.value) }))} /></div>
          <div className="field"><label>Lab ID (for receipt)</label>
            <input value={labId} onChange={e => setLabId(e.target.value)} placeholder="laboratory uuid" /></div>
        </div>
      </div>

      <div className="card">
        <h3 style={{ marginTop: 0 }}>{scope === "current" ? "Current work" : "Past work"} · {session.activeRole}</h3>
        <table className="table">
          <thead>
            <tr>
              <th>Kind</th>
              <th>Status</th>
              <th>Sample</th>
              <th>Assignment</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {items.length === 0 && (
              <tr><td colSpan={5} className="muted">No work items</td></tr>
            )}
            {items.map((it: any) => {
              const asg = it.assignmentId || it.id
              const sampleId = it.sampleId
              return (
                <tr key={asg || sampleId || JSON.stringify(it)}>
                  <td>{it.kind || it.itemType || "—"}</td>
                  <td><span className="badge">{it.status}</span></td>
                  <td className="muted" style={{ fontSize: "0.8rem" }}>{sampleId || "—"}</td>
                  <td className="muted" style={{ fontSize: "0.8rem" }}>{asg || "—"}</td>
                  <td>
                    <div className="row" style={{ gap: 6, flexWrap: "wrap" }}>
                      {it.status === "offered" && asg && (
                        <>
                          <button disabled={busy === asg} onClick={() => accept(asg)}>Accept</button>
                          <button className="secondary" disabled={busy === asg} onClick={() => decline(asg)}>Decline</button>
                        </>
                      )}
                      {(it.status === "accepted" || it.status === "in_progress") && it.kind === "collection" && asg && sampleId && (
                        <button disabled={busy === asg} onClick={() => collect(asg, sampleId)}>Collect & seal</button>
                      )}
                      {(it.status === "accepted" || it.status === "in_progress") && it.kind === "laboratory" && sampleId && (
                        <button disabled={busy === sampleId} onClick={() => confirmReceipt(sampleId)}>Confirm receipt</button>
                      )}
                      {asg && (
                        <button className="secondary" onClick={() => updateLoc(asg)}>Record location</button>
                      )}
                    </div>
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}
"""

