export default function App() {
  const [session, setSession] = useState<AuthSession | null>(() => getSession())
  const [page, setPage] = useState<Page>('work')
  const [bootstrap, setBootstrap] = useState<any>(null)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const nav = useMemo(() => session ? pagesForRole(session.activeRole) : [], [session])

  useEffect(() => {
    if (!session) return
    let cancelled = false
    ;(async () => {
      try {
        const data = await api('/ui/bootstrap')
        if (!cancelled) setBootstrap(data)
      } catch (e: any) {
        if (e?.status === 401) {
          clearSession()
          setSession(null)
        }
      }
    })()
    return () => { cancelled = true }
  }, [session?.token, session?.activeRole])

  useEffect(() => {
    if (!session) return
    const allowed = pagesForRole(session.activeRole).map(p => p.id)
    if (!allowed.includes(page)) setPage(allowed[0])
  }, [session?.activeRole])

  async function onLogin(username: string, password: string) {
    setError('')
    setLoading(true)
    try {
      const data = await api<any>('/authenticate-user', {
        auth: false,
        body: { username, password },
      })
      const s: AuthSession = {
        token: data.sessionToken || data.accessToken || data.token,
        userId: data.userId,
        username: data.username || username,
        displayName: data.displayName || data.fullName || data.username || username,
        roles: data.roles || [],
        activeRole: data.activeRole || (data.roles && data.roles[0]) || '',
        assignedLocationIds: data.assignedLocationIds || [],
        certifications: data.certifications || [],
      }
      saveSession(s)
      setSession(s)
      setPage(pagesForRole(s.activeRole)[0].id)
    } catch (e: any) {
      setError(e.message || 'Login failed')
    } finally {
      setLoading(false)
    }
  }

  async function switchRole(role: Role) {
    if (!session || role === session.activeRole) return
    setError('')
    try {
      const data = await api<any>('/select-active-role', { body: { role } })
      const next = {
        ...session,
        activeRole: (data.activeRole || role) as Role,
        roles: data.roles || session.roles,
      }
      saveSession(next)
      setSession(next)
    } catch (e: any) {
      setError(e.message || 'Role switch failed')
    }
  }

  function logout() {
    clearSession()
    setSession(null)
    setBootstrap(null)
  }

