sample = r'''import { useState } from 'react'
import { api, AuthSession } from '../api'

export default function SamplePage({ session }: { session: AuthSession }) {
  const [sampleId, setSampleId] = useState('')
  const [state, setState] = useState<any>(null)
  const [lifecycle, setLifecycle] = useState<any>(null)
  const [plan, setPlan] = useState<any>(null)
  const [error, setError] = useState('')

  async function load() {
    setError('')
    setState(null)
    setLifecycle(null)
    setPlan(null)
    try {
      const st = await api(`/read-sample-state/${encodeURIComponent(sampleId)}`)
      setState(st)
      try {
        const lc = await api('/read-sample-lifecycle', { body: { sampleId } })
        setLifecycle(lc)
      } catch { /* optional */ }
      const journeyId = st?.activeJourneyId || st?.journeyId
      if (journeyId) {
        try {
          const p = await api('/read-journey-plan', { body: { journeyId } })
          setPlan(p)
        } catch { /* optional */ }
      }
    } catch (e: any) {
      setError(e.message)
    }
  }

  const events = (lifecycle?.events || lifecycle?.timeline || lifecycle?.statusHistory || []) as any[]
  const exception = state?.exception || state?.exceptionReason || state?.hasException
  const loc = state?.lastKnownLocation || state?.location || state?.coordinate
  const stale = !!(state?.locationStale || state?.stale)
  const progress = state?.routeProgress || state?.progress || plan?.progress

  return (
    <div className="grid">
      <div className="card">
        <h3 style={{ marginTop: 0 }}>Sample lookup</h3>
        <div className="row">
          <div className="field">
            <label htmlFor="sample-id-input">Sample ID</label>
            <input id="sample-id-input" value={sampleId} onChange={e => setSampleId(e.target.value)} placeholder="uuid" aria-label="Sample ID" />
          </div>
          <div className="field" style={{ display: 'flex', alignItems: 'end' }}>
            <button onClick={load} aria-label="Load sample">Load sample</button>
          </div>
        </div>
        {error && <div className="error-box" role="alert">{error}</div>}
      </div>

      {state && (
        <div className="card" aria-label="Sample current state">
          <h3 style={{ marginTop: 0 }}>Current state</h3>
          <div className="row">
            <div>
              <span className="muted">Status</span>
              <div><span className="badge" aria-label={`Status ${state.status}`}>{state.status}</span></div>
            </div>
            <div>
              <span className="muted">Custodian</span>
              <div aria-label="Current custodian">{state.currentHolderName || state.currentHolderId || state.custodianId || '—'}</div>
            </div>
            <div>
              <span className="muted">Sealed</span>
              <div>{state.sealed ? 'yes' : 'no'}</div>
            </div>
            <div>
              <span className="muted">Location freshness</span>
              <div>
                {stale
                  ? <span className="badge warn" aria-label="Location stale">stale</span>
                  : <span className="badge ok" aria-label="Location fresh">fresh</span>}
              </div>
            </div>
            <div>
              <span className="muted">Last update</span>
              <div aria-label="Last location update">{state.lastLocationAt || state.updatedAt || state.lastUpdatedAt || '—'}</div>
            </div>
          </div>
          <div className="row" style={{ marginTop: '0.75rem' }}>
            <div>
              <span className="muted">Last known location</span>
              <div aria-label="Sample location">
                {loc
                  ? `${loc.latitude ?? loc.lat}, ${loc.longitude ?? loc.lng}`
                  : '—'}
              </div>
            </div>
            <div>
              <span className="muted">Route progress</span>
              <div aria-label="Route progress">{typeof progress === 'object' ? JSON.stringify(progress) : (progress ?? '—')}</div>
            </div>
            <div>
              <span className="muted">Exception</span>
              <div aria-label="Exception flag">
                {exception
                  ? <span className="badge err">{typeof exception === 'string' ? exception : (exception.reason || 'exception')}</span>
                  : <span className="badge ok">none</span>}
              </div>
            </div>
          </div>
        </div>
      )}

      {lifecycle && (
        <div className="card" aria-label="Sample status history">
          <h3 style={{ marginTop: 0 }}>Ordered status history</h3>
          <div className="timeline" role="list">
            {events.map((ev: any, i: number) => (
              <div className="timeline-item" role="listitem" key={i}>
                <div>
                  <strong>{ev.status || ev.type || ev.action || ev.eventType}</strong>{' '}
                  <span className="muted">{ev.at || ev.occurredAt || ev.timestamp}</span>
                </div>
                <div className="muted">{ev.summary || ev.message || ev.note || ''}</div>
              </div>
            ))}
          </div>
          {!events.length && (
            <pre className="json">{JSON.stringify(lifecycle, null, 2)}</pre>
          )}
        </div>
      )}

      {plan && (
        <div className="card" aria-label="Journey plan">
          <h3 style={{ marginTop: 0 }}>Journey plan</h3>
          <pre className="json">{JSON.stringify(plan, null, 2)}</pre>
        </div>
      )}
      <div className="muted">Role: {session.activeRole}</div>
    </div>
  )
}
'''

