              </div>
            </div>
            <div>
              <span className="muted">Last update</span>
              <div aria-label="Last location update">{state.lastLocationAt || state.updatedAt || state.lastUpdatedAt || '—'}</div>
            </div>
          </div>
          <div className="row" style={{ marginTop: '0.75rem' }}>
            <div>
              <span className="muted">Last known location</span>
              <div aria-label="Sample location">
                {loc
                  ? `${loc.latitude ?? loc.lat}, ${loc.longitude ?? loc.lng}`
                  : '—'}
              </div>
            </div>
            <div>
              <span className="muted">Route progress</span>
              <div aria-label="Route progress">{typeof progress === 'object' ? JSON.stringify(progress) : (progress ?? '—')}</div>
            </div>
            <div>
              <span className="muted">Exception</span>
              <div aria-label="Exception flag">
                {exception
                  ? <span className="badge err">{typeof exception === 'string' ? exception : (exception.reason || 'exception')}</span>
                  : <span className="badge ok">none</span>}
              </div>
            </div>
          </div>
        </div>
      )}

      {lifecycle && (
        <div className="card" aria-label="Sample status history">
          <h3 style={{ marginTop: 0 }}>Ordered status history</h3>
